static bool getProjectSyncEnabled()
{
  // Recurso reservado para uma atualizacao futura.
  return false;
}

static void toggleProjectSync()
{
  showComingSoonFeatureMessage();
}

static std::string getCurrentProjectSignature()
{
  char path[2048] = "";
  ReaProject* project = getCurrentProject(path, static_cast<int>(sizeof(path)));

  std::ostringstream oss;
  oss << reinterpret_cast<std::uintptr_t>(project) << "|" << normalizeSlashes(path);
  return oss.str();
}

static std::string getProjectAutoOpenMode()
{
  if (!GetProjExtState_ptr) return std::string();

  char value[64] = "";
  char path[2048] = "";
  ReaProject* project = getCurrentProject(path, static_cast<int>(sizeof(path)));

  // Igual a logica de startup action por projeto da SWS: a configuracao fica no .RPP.
  GetProjExtState_ptr(project, kExtStateSection, kProjectAutoOpenModeKey, value, static_cast<int>(sizeof(value)));

  const std::string mode = value;
  return isAutoOpenModeValue(mode) ? mode : std::string();
}

static void setProjectAutoOpenModeRaw(const char* mode, bool showError)
{
  if (!SetProjExtState_ptr) {
    if (showError) {
      showDiagnostic("REAPER nao entregou a API SetProjExtState para salvar configuracao deste projeto.");
    }
    return;
  }

  const std::string safeMode = (mode && isAutoOpenModeValue(mode)) ? mode : "";
  char path[2048] = "";
  ReaProject* project = getCurrentProject(path, static_cast<int>(sizeof(path)));

  // Igual a SWS: grava no ProjExtState do projeto. Para ficar permanente, salve o .RPP.
  SetProjExtState_ptr(project, kExtStateSection, kProjectAutoOpenModeKey, safeMode.c_str());

  // Evita que o timer abra imediatamente ao marcar a opcao; ela passa a valer
  // quando este projeto for aberto/carregado de novo.
  if (!safeMode.empty()) {
    g_state.autoOpenedProjectSignature = getCurrentProjectSignature() + "|" + safeMode;
  } else {
    g_state.autoOpenedProjectSignature.clear();
  }
}

static void setProjectAutoOpenMode(const char* mode)
{
  setProjectAutoOpenModeRaw(mode, true);
}

static void normalizeAutoOpenConflict()
{
  // Se uma configuracao antiga deixou REAPER e projeto ativos ao mesmo tempo,
  // o projeto ganha por ser mais especifico. Isso evita duplo disparo ao abrir.
  if (!getAutoOpenMode().empty() && !getProjectAutoOpenMode().empty()) {
    setAutoOpenModeRaw("", false);
  }
}

static const char* displayNameForAutoOpenMode(const char* mode)
{
  if (mode && std::strcmp(mode, "native") == 0) return "VS Hook";
  for (const ScriptEntry& script : g_scripts) {
    if (mode && std::strcmp(script.autoOpenMode, mode) == 0) {
      return script.displayName;
    }
  }
  return "VS Hook";
}

static void toggleAutoOpenMode(const char* mode)
{
  const std::string currentMode = getAutoOpenMode();

  if (mode && currentMode == mode) {
    setAutoOpenMode("");
    showDiagnostic(std::string(displayNameForAutoOpenMode(mode)) + " nao vai mais iniciar junto com o REAPER.");
    return;
  }

  // Regra de exclusividade: escolher iniciar junto com o REAPER desmarca
  // qualquer configuracao deste projeto, para nao existir duplo disparo.
  setProjectAutoOpenModeRaw("", false);
  setAutoOpenMode(mode);
  showDiagnostic(std::string(displayNameForAutoOpenMode(mode)) + " configurado para iniciar junto com o REAPER. A opcao deste projeto foi desmarcada.");
}

static void toggleProjectAutoOpenMode(const char* mode)
{
  const std::string currentMode = getProjectAutoOpenMode();

  if (mode && currentMode == mode) {
    setProjectAutoOpenMode("");
    showDiagnostic(std::string(displayNameForAutoOpenMode(mode)) + " nao vai mais iniciar junto com ESTE projeto.");
    return;
  }

  // Regra de exclusividade: escolher iniciar junto com ESTE projeto desmarca
  // o auto-inicio global com o REAPER, para nao existir conflito.
  setAutoOpenModeRaw("", false);
  setProjectAutoOpenMode(mode);
  showDiagnostic(std::string(displayNameForAutoOpenMode(mode)) + " configurado para iniciar junto com ESTE projeto. O auto-inicio com o REAPER foi desmarcado. Salve o projeto para gravar essa configuracao no RPP.");
}

static void runScriptByAutoOpenMode(const std::string& mode)
{
  if (!isAutoOpenModeValue(mode)) return;
  if (mode == "native") {
    nativeOpenAppActivePanel();
    return;
  }

  for (ScriptEntry& script : g_scripts) {
    if (mode == script.autoOpenMode) {
      runScript(script, false);
      return;
    }
  }
}

static ScriptEntry* findScriptByCommand(int command)
{
  for (ScriptEntry& script : g_scripts) {
    if (script.commandId != 0 && command == script.commandId) {
      return &script;
    }
  }
  return nullptr;
}

static void toggleNativeInterface()
{
  if (nativeAppActivePanelIsOpen()) nativeCloseAppActivePanel();
  else nativeOpenAppActivePanel();
}

// Necessario para cliques vindos do menu Extensions e tambem chamadas normais da action list.
static bool hookCommand(int command, int flag)
{
  (void)flag;

  if (g_repeatShortcutCommandId != 0 &&
      command == g_repeatShortcutCommandId) {
    if (Main_OnCommand_ptr) Main_OnCommand_ptr(1068, 0);
    return true;
  }
  if (handleTransportQueueStopCommand(command)) return true;
  if (g_nativeInterfaceCommandId != 0 && command == g_nativeInterfaceCommandId) {
    toggleNativeInterface();
    return true;
  }
  if (g_timecodeReceiveCommandId != 0 && command == g_timecodeReceiveCommandId) {
    toggleTimecodeMode("receive");
    return true;
  }
  if (g_timecodeTransmitterCommandId != 0 && command == g_timecodeTransmitterCommandId) {
    toggleTimecodeMode("transmitter");
    return true;
  }
  if (g_projectSyncCommandId != 0 && command == g_projectSyncCommandId) {
    toggleProjectSync();
    return true;
  }
  if (g_telepromptOneCommandId != 0 &&
      command == g_telepromptOneCommandId) {
    nativeToggleTelepromptWindow(1);
    return true;
  }
  if (g_telepromptTwoCommandId != 0 &&
      command == g_telepromptTwoCommandId) {
    nativeToggleTelepromptWindow(2);
    return true;
  }
  if (g_telepromptSettingsCommandId != 0 &&
      command == g_telepromptSettingsCommandId) {
    nativeOpenTelepromptSettings();
    return true;
  }
  if (g_recadosCommandId != 0 &&
      command == g_recadosCommandId) {
    nativeOpenRecadosApp();
    return true;
  }
  for (AutoOpenEntry& entry : g_autoOpenEntries) {
    if (entry.commandId != 0 && command == entry.commandId) {
      toggleAutoOpenMode(entry.autoOpenMode);
      return true;
    }
  }

  for (AutoOpenEntry& entry : g_projectAutoOpenEntries) {
    if (entry.commandId != 0 && command == entry.commandId) {
      toggleProjectAutoOpenMode(entry.autoOpenMode);
      return true;
    }
  }

  ScriptEntry* script = findScriptByCommand(command);
  if (script) {
    runScript(*script);
    return true;
  }

  return false;
}

// Necessario para atalhos, MIDI e alguns disparos internos do REAPER.
static bool hookCommand2(KbdSectionInfo* sec, int command, int val, int val2, int relmode, HWND hwnd)
{
  (void)sec;
  (void)val;
  (void)val2;
  (void)relmode;
  (void)hwnd;

  if (g_repeatShortcutCommandId != 0 &&
      command == g_repeatShortcutCommandId) {
    if (Main_OnCommand_ptr) Main_OnCommand_ptr(1068, 0);
    return true;
  }
  if (handleTransportQueueStopCommand(command)) return true;
  if (g_nativeInterfaceCommandId != 0 && command == g_nativeInterfaceCommandId) {
    toggleNativeInterface();
    return true;
  }
  if (g_timecodeReceiveCommandId != 0 && command == g_timecodeReceiveCommandId) {
    toggleTimecodeMode("receive");
    return true;
  }
  if (g_timecodeTransmitterCommandId != 0 && command == g_timecodeTransmitterCommandId) {
    toggleTimecodeMode("transmitter");
    return true;
  }
  if (g_projectSyncCommandId != 0 && command == g_projectSyncCommandId) {
    toggleProjectSync();
    return true;
  }
  if (g_telepromptOneCommandId != 0 &&
      command == g_telepromptOneCommandId) {
    nativeToggleTelepromptWindow(1);
    return true;
  }
  if (g_telepromptTwoCommandId != 0 &&
      command == g_telepromptTwoCommandId) {
    nativeToggleTelepromptWindow(2);
    return true;
  }
  if (g_telepromptSettingsCommandId != 0 &&
      command == g_telepromptSettingsCommandId) {
    nativeOpenTelepromptSettings();
    return true;
  }
  if (g_recadosCommandId != 0 &&
      command == g_recadosCommandId) {
    nativeOpenRecadosApp();
    return true;
  }
  for (AutoOpenEntry& entry : g_autoOpenEntries) {
    if (entry.commandId != 0 && command == entry.commandId) {
      toggleAutoOpenMode(entry.autoOpenMode);
      return true;
    }
  }

  for (AutoOpenEntry& entry : g_projectAutoOpenEntries) {
    if (entry.commandId != 0 && command == entry.commandId) {
      toggleProjectAutoOpenMode(entry.autoOpenMode);
      return true;
    }
  }

  ScriptEntry* script = findScriptByCommand(command);
  if (script) {
    runScript(*script);
    return true;
  }

  return false;
}

static int toggleActionState(int commandId)
{
  normalizeAutoOpenConflict();

  if (g_nativeInterfaceCommandId != 0 && commandId == g_nativeInterfaceCommandId) {
    return nativeAppActivePanelIsOpen() ? 1 : 0;
  }
  if (g_timecodeReceiveCommandId != 0 && commandId == g_timecodeReceiveCommandId) {
    return getTimecodeMode() == "receive" ? 1 : 0;
  }
  if (g_timecodeTransmitterCommandId != 0 && commandId == g_timecodeTransmitterCommandId) {
    return getTimecodeMode() == "transmitter" ? 1 : 0;
  }
  if (g_projectSyncCommandId != 0 && commandId == g_projectSyncCommandId) {
    return getProjectSyncEnabled() ? 1 : 0;
  }
  if (g_telepromptOneCommandId != 0 &&
      commandId == g_telepromptOneCommandId) {
    return nativeTelepromptWindowIsOpen(1) ? 1 : 0;
  }
  if (g_telepromptTwoCommandId != 0 &&
      commandId == g_telepromptTwoCommandId) {
    return nativeTelepromptWindowIsOpen(2) ? 1 : 0;
  }

  for (AutoOpenEntry& entry : g_autoOpenEntries) {
    if (entry.commandId != 0 && commandId == entry.commandId) {
      return getAutoOpenMode() == entry.autoOpenMode ? 1 : 0;
    }
  }

  for (AutoOpenEntry& entry : g_projectAutoOpenEntries) {
    if (entry.commandId != 0 && commandId == entry.commandId) {
      return getProjectAutoOpenMode() == entry.autoOpenMode ? 1 : 0;
    }
  }

  const std::string activeScriptMode = getExclusiveActiveScriptMode();
  for (ScriptEntry& script : g_scripts) {
    if (script.commandId != 0 && commandId == script.commandId) {
      return script.autoOpenMode && activeScriptMode == script.autoOpenMode ? 1 : 0;
    }
  }

  return -1;
}

static void appendMenuString(HMENU hMenu, const char* text, int commandId, bool checked)
{
  if (!hMenu || !text || commandId == 0) return;
#ifdef _WIN32
  std::wstring wideText = utf8ToWide(text);
  MENUITEMINFOW mi = { sizeof(MENUITEMINFOW), };
  mi.fMask = MIIM_STRING | MIIM_ID | MIIM_STATE;
  mi.fType = MFT_STRING;
  mi.fState = checked ? MFS_CHECKED : MFS_UNCHECKED;
  mi.dwTypeData = wideText.data();
  mi.wID = commandId;
  InsertMenuItemW(hMenu, GetMenuItemCount(hMenu), true, &mi);
#else
  MENUITEMINFO mi = { sizeof(MENUITEMINFO), };
  mi.fMask = MIIM_TYPE | MIIM_ID | MIIM_STATE;
  mi.fType = MFT_STRING;
  mi.fState = checked ? MFS_CHECKED : MFS_UNCHECKED;
  mi.dwTypeData = (char*)text;
  mi.wID = commandId;
  InsertMenuItem(hMenu, GetMenuItemCount(hMenu), true, &mi);
#endif
}

static void insertMenuSubMenu(HMENU hMenu, HMENU subMenu, const char* text, int position)
{
  if (!hMenu || !subMenu || !text) return;
#ifdef _WIN32
  std::wstring wideText = utf8ToWide(text);
  MENUITEMINFOW mi = { sizeof(MENUITEMINFOW), };
  mi.fMask = MIIM_SUBMENU | MIIM_STRING | MIIM_STATE;
  mi.fType = MFT_STRING;
  mi.fState = MFS_ENABLED;
  mi.hSubMenu = subMenu;
  mi.dwTypeData = wideText.data();
  const int itemCount = GetMenuItemCount(hMenu);
  const int safePosition =
    position < 0 ? itemCount : std::min(position, itemCount);
  InsertMenuItemW(hMenu, safePosition, true, &mi);
#else
  MENUITEMINFO mi = { sizeof(MENUITEMINFO), };
  mi.fMask = MIIM_SUBMENU | MIIM_TYPE | MIIM_STATE;
  mi.fType = MFT_STRING;
  mi.fState = MFS_ENABLED;
  mi.hSubMenu = subMenu;
  mi.dwTypeData = (char*)text;
  const int itemCount = GetMenuItemCount(hMenu);
  const int safePosition = position < 0 ? itemCount : std::min(position, itemCount);
  InsertMenuItem(hMenu, safePosition, true, &mi);
#endif
}

static void setMenuCommandChecked(HMENU hMenu, int commandId, bool checked)
{
  if (!hMenu || commandId == 0) return;
#ifdef _WIN32
  CheckMenuItem(hMenu, static_cast<UINT>(commandId), MF_BYCOMMAND | (checked ? MF_CHECKED : MF_UNCHECKED));
#else
  CheckMenuItem(hMenu, commandId, MF_BYCOMMAND | (checked ? MF_CHECKED : MF_UNCHECKED));
#endif
}

static void menuHook(const char* menustr, HMENU hMenu, int flag)
{
  if (!menustr || !hMenu) return;
  if (std::strcmp(menustr, "Main extensions") != 0) return;

  normalizeAutoOpenConflict();

  const std::string autoMode = getAutoOpenMode();
  const std::string projectAutoMode = getProjectAutoOpenMode();

  // flag 1 acontece quando o menu vai ser exibido. Atualiza a marcacao
  // imediatamente, sem precisar reiniciar o REAPER.
  if (flag == 1) {
    setMenuCommandChecked(hMenu, g_nativeInterfaceCommandId, nativeAppActivePanelIsOpen());
    for (AutoOpenEntry& entry : g_autoOpenEntries) {
      setMenuCommandChecked(hMenu, entry.commandId, autoMode == entry.autoOpenMode);
    }
    for (AutoOpenEntry& entry : g_projectAutoOpenEntries) {
      setMenuCommandChecked(hMenu, entry.commandId, projectAutoMode == entry.autoOpenMode);
    }
    const std::string timecodeMode = getTimecodeMode();
    setMenuCommandChecked(hMenu, g_timecodeReceiveCommandId, timecodeMode == "receive");
    setMenuCommandChecked(hMenu, g_timecodeTransmitterCommandId, timecodeMode == "transmitter");
    setMenuCommandChecked(hMenu, g_projectSyncCommandId, getProjectSyncEnabled());
    setMenuCommandChecked(hMenu, g_telepromptOneCommandId,
      nativeTelepromptWindowIsOpen(1));
    setMenuCommandChecked(hMenu, g_telepromptTwoCommandId,
      nativeTelepromptWindowIsOpen(2));
    return;
  }

  if (flag != 0) return;

  // Mesmo modelo de submenus usado pela SWS. O usuario nao informa Command ID:
  // cada opcao aponta diretamente para uma action interna deste produto.
  HMENU vsHookMenu = CreatePopupMenu();
  HMENU telepromptMenu = CreatePopupMenu();
  HMENU startupMenu = CreatePopupMenu();
  HMENU timecodeMenu = CreatePopupMenu();
  HMENU projectSyncMenu = CreatePopupMenu();
  if (!vsHookMenu || !telepromptMenu || !startupMenu ||
      !timecodeMenu || !projectSyncMenu) return;

  appendMenuString(vsHookMenu, "Executar", g_nativeInterfaceCommandId, nativeAppActivePanelIsOpen());
  appendMenuString(telepromptMenu, "Abrir Teleprompt 1",
    g_telepromptOneCommandId, nativeTelepromptWindowIsOpen(1));
  appendMenuString(telepromptMenu, "Abrir Teleprompt 2",
    g_telepromptTwoCommandId, nativeTelepromptWindowIsOpen(2));
  appendMenuString(telepromptMenu, "Configurações",
    g_telepromptSettingsCommandId, false);
  insertMenuSubMenu(vsHookMenu, telepromptMenu, "Teleprompt", -1);
  appendMenuString(
    vsHookMenu, "Recados", g_recadosCommandId, false);

  appendMenuString(
    startupMenu,
    g_autoOpenEntries[0].displayName,
    g_autoOpenEntries[0].commandId,
    autoMode == g_autoOpenEntries[0].autoOpenMode);
  appendMenuString(
    startupMenu,
    g_projectAutoOpenEntries[0].displayName,
    g_projectAutoOpenEntries[0].commandId,
    projectAutoMode == g_projectAutoOpenEntries[0].autoOpenMode);
  insertMenuSubMenu(vsHookMenu, startupMenu, "Startup", -1);

  const std::string timecodeMode = getTimecodeMode();
  appendMenuString(timecodeMenu, "Receive", g_timecodeReceiveCommandId, timecodeMode == "receive");
  appendMenuString(timecodeMenu, "Transmitter", g_timecodeTransmitterCommandId, timecodeMode == "transmitter");
  insertMenuSubMenu(vsHookMenu, timecodeMenu, "Timecode", -1);

  appendMenuString(projectSyncMenu, "Sync to project", g_projectSyncCommandId, getProjectSyncEnabled());
  insertMenuSubMenu(vsHookMenu, projectSyncMenu, "Project Sync", -1);

  // VS Hook aparece como uma unica entrada no menu Extensions e abre tudo no
  // submenu lateral: Executar, Teleprompt, Startup, Timecode e Project Sync.
  insertMenuSubMenu(hMenu, vsHookMenu, "VS Hook", 0);
}



