nativeTechnicalNoticeSettingsJsonLocked()
{
  const NativeTechnicalNoticeSettings& settings =
    g_nativeTechnicalNoticeSettings;
  std::ostringstream json;
  json << "{";
  json << "\"textColor\":"
       << nativeJsonString(settings.textColor) << ",";
  json << "\"backgroundColor\":"
       << nativeJsonString(settings.backgroundColor) << ",";
  json << "\"flashColor\":"
       << nativeJsonString(settings.flashColor) << ",";
  json << "\"fontFamily\":"
       << nativeJsonString(settings.fontFamily) << ",";
  json << "\"window1Enabled\":"
       << (settings.window1Enabled ? "true" : "false") << ",";
  json << "\"window2Enabled\":"
       << (settings.window2Enabled ? "true" : "false") << ",";
  json << "\"emojiEnabled\":"
       << (settings.emojiEnabled ? "true" : "false") << ",";
  json << "\"cleanDisplay\":"
       << (settings.cleanDisplay ? "true" : "false") << ",";
  json << "\"emoji\":"
       << nativeJsonString(settings.emoji) << ",";
  json << "\"recadosTemplates\":[";
  for (size_t index = 0;
       index < settings.templates.size(); ++index) {
    if (index > 0) json << ",";
    json << nativeJsonString(settings.templates[index]);
  }
  json << "],\"recadosImages\":[";
  for (size_t index = 0;
       index < settings.templateImages.size(); ++index) {
    if (index > 0) json << ",";
    json << nativeJsonString(
      settings.templateImages[index]);
  }
  json << "]}";
  return json.str();
}

static std::string nativeTechnicalNoticeJsonLocked(
  int64_t nowMs)
{
  if (!nativeTechnicalNoticeIsActiveLocked(nowMs)) {
    return "null";
  }
  const NativeTechnicalNotice& notice =
    g_nativeTechnicalNotice;
  std::ostringstream json;
  json << "{";
  json << "\"id\":" << nativeJsonString(notice.id) << ",";
  json << "\"text\":" << nativeJsonString(notice.text) << ",";
  json << "\"message\":" << nativeJsonString(notice.text) << ",";
  json << "\"imagePath\":"
       << nativeJsonString(notice.imagePath) << ",";
  json << "\"imageUrl\":"
       << nativeJsonString(
            notice.imagePath.empty()
              ? std::string()
              : std::string("/media?path=") +
                  nativeUrlEncode(notice.imagePath))
       << ",";
  json << "\"source\":" << nativeJsonString(notice.source) << ",";
  json << "\"priority\":" << notice.priority << ",";
  json << "\"createdAt\":" << notice.createdAtMs << ",";
  json << "\"updatedAt\":" << notice.updatedAtMs << ",";
  json << "\"expiresAt\":" << notice.expiresAtMs << ",";
  json << "\"durationMs\":" << notice.durationMs << ",";
  json << "\"pausedRemainingMs\":"
       << notice.pausedRemainingMs << ",";
  json << "\"pinned\":"
       << (notice.pinned ? "true" : "false");
  json << "}";
  return json.str();
}

