static double nativeUiLivePartsRegressRatio(
  const NativeAppActivePanelModel::PartColumn& column)
{
  if (!column.regressActive) return 0.0;
  const double total = column.regressEnd - column.regressStart;
  if (total <= 0.001) return 0.0;

  double current = column.regressStart;
  ReaProject* project = getCurrentProject(nullptr, 0);
  const int playState = project && GetPlayStateEx_ptr
    ? GetPlayStateEx_ptr(project) : 0;
  if (project && playState != 0 && GetPlayPositionEx_ptr) {
    current = GetPlayPositionEx_ptr(project);
  } else if (project && GetCursorPositionEx_ptr) {
    current = GetCursorPositionEx_ptr(project);
  } else {
    return std::max(0.0, std::min(1.0,
      column.regressRatio));
  }

  // Mesma regra do Lua: cheia antes/do ponto de engatilhar e vazia ao chegar
  // no proximo marker valido (ou no fim da regiao de origem).
  if (current <= column.regressStart) return 1.0;
  if (current >= column.regressEnd) return 0.0;
  const double remaining = column.regressEnd - current;
  return std::max(0.0, std::min(1.0,
    remaining / total));
}

static void nativePaintPartsColumn(
  HDC dc,
  const RECT& columnRect,
  const NativeAppActivePanelModel::PartColumn& column,
  bool parts2,
  HFONT labelFont,
  HFONT statusFont,
  const std::map<std::string, std::string>& visualPrefs)
{
  RECT& panelHitRect = parts2 ? g_nativeMainParts2Rect : g_nativeMainParts1Rect;
  RECT& headerHitRect = parts2 ? g_nativeMainParts2HeaderRect : g_nativeMainParts1HeaderRect;
  RECT& listHitRect = parts2 ? g_nativeMainParts2ListRect : g_nativeMainParts1ListRect;
  int& scrollPixels = parts2 ? g_nativeParts2ScrollPixels : g_nativeParts1ScrollPixels;
  auto& rowHits = parts2
    ? g_nativeParts2RowHits
    : g_nativeParts1RowHits;
  auto& rowOffsets = parts2
    ? g_nativeParts2RowOffsets
    : g_nativeParts1RowOffsets;
  auto& rowHeights = parts2
    ? g_nativeParts2RowHeights
    : g_nativeParts1RowHeights;
  int& storedMaxScroll = parts2
    ? g_nativeParts2MaxScrollPixels
    : g_nativeParts1MaxScrollPixels;
  rowHits.clear();
  rowOffsets.clear();
  rowHeights.clear();
  storedMaxScroll = 0;
  panelHitRect = columnRect;

  if (columnRect.right <= columnRect.left || columnRect.bottom <= columnRect.top) {
    headerHitRect = RECT{0, 0, 0, 0};
    listHitRect = RECT{0, 0, 0, 0};
    scrollPixels = 0;
    return;
  }

  const NativeUiListLayout listLayout =
    nativeUiCurrentListLayout(visualPrefs);
  const COLORREF listPanelFill =
    nativeUiListPanelBackgroundColor(visualPrefs);
  const COLORREF selectionArrowColor =
    nativeUiNamedVisualColor(
      nativeUiVisualPref(visualPrefs,
        "parts_selection_arrow_color_mode",
        "yellow"),
      "yellow");
  const int titleH = 18;
  const int sourceH = 22;
  nativeAppActiveFillRoundRect(dc, columnRect,
    listPanelFill, RGB(74, 82, 89), 0);

  RECT titleRect{columnRect.left, columnRect.top, columnRect.right,
    std::min(columnRect.bottom, columnRect.top + titleH)};
  nativeAppActiveFillRect(dc, titleRect, RGB(20, 23, 26));
  RECT titleText{titleRect.left + 7, titleRect.top + 1, titleRect.right - 6, titleRect.bottom - 1};
  nativeAppActiveDrawText(dc, parts2 ? "Parts 2" : "Parts 1", titleText,
    DT_LEFT | DT_VCENTER | DT_SINGLELINE | DT_END_ELLIPSIS | DT_NOPREFIX,
    RGB(248, 250, 252), labelFont);

  headerHitRect = RECT{columnRect.left + 1, titleRect.bottom,
    columnRect.right - 1, std::min(columnRect.bottom, titleRect.bottom + sourceH)};
  const std::string virtualStartId = column.hasSource
    ? std::string("start:") + column.sourceId : std::string();
  const bool headerArmed = column.hasSource &&
    g_nativeAppActivePanelModel.armedMarkerId == virtualStartId;
  const bool headerSelected = column.hasSource &&
    g_nativeAppActivePanelModel.selectedMarkerId == virtualStartId;
  const bool headerFocused = (parts2 && g_nativeMainNavigationFocus == "parts2") ||
    (!parts2 && g_nativeMainNavigationFocus == "parts");

  COLORREF headerFill = RGB(10, 13, 18);
  COLORREF headerEdge = RGB(46, 51, 61);
  COLORREF headerTextColor = column.hasSource ? RGB(255, 224, 46) : RGB(100, 116, 139);
  if (headerArmed) {
    headerFill = nativePartsBlinkBright() ? RGB(250, 204, 21) : RGB(116, 95, 10);
    headerEdge = RGB(255, 153, 0);
    headerTextColor = RGB(8, 12, 18);
  } else if (headerSelected) {
    headerFill = headerFocused ? RGB(8, 87, 184) : RGB(20, 65, 117);
    headerEdge = headerFocused ? RGB(77, 179, 255) : RGB(50, 105, 165);
    headerTextColor = RGB(255, 255, 255);
  }
  nativeAppActiveFillRoundRect(dc, headerHitRect,
    headerFill, headerEdge, 0);
  const std::string sourceText = column.hasSource
    ? nativeUpperNamePtBrKeepParentheses(
        column.sourceName) + " - INÍCIO"
    : "-";
  const bool headerShowsSelectionArrow =
    headerSelected && !headerArmed;
  if (headerShowsSelectionArrow) {
    nativeUiDrawSelectionArrow(dc,
      headerHitRect.left + 6,
      (headerHitRect.top + headerHitRect.bottom) / 2,
      selectionArrowColor);
  }
  RECT sourceTextRect{
    headerHitRect.left +
      (headerShowsSelectionArrow ? 18 : 6),
    headerHitRect.top + 2,
    headerHitRect.right - 6, headerHitRect.bottom - 5};
  nativeAppActiveDrawText(dc, sourceText, sourceTextRect,
    DT_LEFT | DT_VCENTER | DT_SINGLELINE | DT_END_ELLIPSIS | DT_NOPREFIX,
    headerTextColor, statusFont);
  RECT headerBar{headerHitRect.left + 6, headerHitRect.bottom - 4,
    headerHitRect.right - 6, headerHitRect.bottom - 2};
  nativeAppActiveFillRect(dc, headerBar, RGB(26, 31, 41));
  const double regressRatio =
    nativeUiLivePartsRegressRatio(column);
  if (regressRatio > 0.0) {
    RECT fill = headerBar;
    fill.right = fill.left + std::max(1,
      static_cast<int>(std::floor(
        (fill.right - fill.left) * regressRatio + 0.5)));
    nativeAppActiveFillRect(dc, fill, RGB(255, 214, 20));
  }

  listHitRect = RECT{columnRect.left + 1, headerHitRect.bottom,
    columnRect.right - 1, columnRect.bottom - 1};
  const int viewport = std::max(0, static_cast<int>(listHitRect.bottom - listHitRect.top));
  const int rowCount = static_cast<int>(column.rows.size());
  const int virtualRowCount = rowCount + 3;
  const int baseWidth = std::max(
    1, static_cast<int>(listHitRect.right -
      listHitRect.left) - 8);
  rowOffsets.reserve(static_cast<size_t>(rowCount) + 1);
  rowHeights.reserve(static_cast<size_t>(rowCount));
  int realRowsHeight = 0;
  for (int index = 0; index < rowCount; ++index) {
    rowOffsets.push_back(realRowsHeight);
    const NativeUiPartsRowMetrics metrics =
      nativeUiMeasurePartsRow(dc,
        column.rows[static_cast<size_t>(index)],
        baseWidth, statusFont, listLayout);
    rowHeights.push_back(metrics.height);
    realRowsHeight += metrics.height;
  }
  rowOffsets.push_back(realRowsHeight);
  const int maxScrollPixels = std::max(
    0, realRowsHeight +
      3 * listLayout.singleRowHeight -
      viewport);
  storedMaxScroll = maxScrollPixels;
  scrollPixels = std::max(0, std::min(scrollPixels, maxScrollPixels));

  if (rowCount <= 0 || viewport <= 0) {
    RECT emptyRect{listHitRect.left + 3, listHitRect.top + 2,
      listHitRect.right - 3, listHitRect.bottom - 2};
    nativeAppActiveDrawText(dc, "LISTA VAZIA", emptyRect,
      DT_CENTER | DT_VCENTER | DT_SINGLELINE | DT_END_ELLIPSIS | DT_NOPREFIX,
      RGB(100, 116, 139), statusFont);
    return;
  }

  const RECT clipRect{listHitRect.left, listHitRect.top,
    listHitRect.right - 6, listHitRect.bottom};
  const NativeUiClipState clipState =
    nativeUiBeginClipRect(dc, clipRect);
  int firstRow = 0;
  while (firstRow < rowCount &&
         rowOffsets[static_cast<size_t>(firstRow)] +
             rowHeights[static_cast<size_t>(firstRow)] <=
           scrollPixels) {
    ++firstRow;
  }
  int endRow = firstRow;
  while (endRow < rowCount &&
         rowOffsets[static_cast<size_t>(endRow)] <
           scrollPixels + viewport) {
    ++endRow;
  }
  const int visibleRows = std::max(0, endRow - firstRow);
  for (int i = firstRow; i < endRow; ++i) {
    const auto& row = column.rows[static_cast<size_t>(i)];
    const NativeUiPartsRowMetrics metrics =
      nativeUiMeasurePartsRow(dc, row,
        baseWidth, statusFont, listLayout);
    RECT rowRect{listHitRect.left + 1,
      listHitRect.top +
        rowOffsets[static_cast<size_t>(i)] -
        scrollPixels,
      listHitRect.right - 7,
      listHitRect.top +
        rowOffsets[static_cast<size_t>(i)] +
        rowHeights[static_cast<size_t>(i)] -
        scrollPixels};
    const bool armed = row.id == g_nativeAppActivePanelModel.armedMarkerId;
    const bool selected = row.id == g_nativeAppActivePanelModel.selectedMarkerId;
    const bool focused = (parts2 && g_nativeMainNavigationFocus == "parts2") ||
      (!parts2 && g_nativeMainNavigationFocus == "parts");
    COLORREF fill = ((i + 1) % 2 == 0)
      ? nativeUiBlendColor(listPanelFill,
          RGB(46, 51, 56), 0.58)
      : listPanelFill;
    COLORREF textColor = RGB(255, 224, 46);
    COLORREF edge = RGB(74, 82, 89);
    bool drawEdge = false;
    if (armed) {
      fill = nativePartsBlinkBright() ? RGB(250, 204, 21) : RGB(116, 95, 10);
      textColor = RGB(8, 12, 18);
      edge = RGB(255, 153, 0);
      drawEdge = true;
    } else if (selected) {
      fill = focused
        ? RGB(26, 128, 242)
        : nativeUiBlendColor(
            listPanelFill,
            RGB(20, 77, 148), 0.58);
      textColor = focused
        ? RGB(13, 13, 13)
        : RGB(224, 240, 255);
      edge = focused
        ? RGB(255, 224, 61)
        : RGB(51, 122, 209);
      drawEdge = true;
    }
    nativeAppActiveFillRect(dc, rowRect, fill);
    if (drawEdge) {
      nativeAppActiveFillRect(dc,
        RECT{rowRect.left, rowRect.top,
          rowRect.right, rowRect.top + 1},
        edge);
      nativeAppActiveFillRect(dc,
        RECT{rowRect.left, rowRect.bottom - 1,
          rowRect.right, rowRect.bottom},
        edge);
      nativeAppActiveFillRect(dc,
        RECT{rowRect.left, rowRect.top,
          rowRect.left + 1, rowRect.bottom},
        edge);
      nativeAppActiveFillRect(dc,
        RECT{rowRect.right - 1, rowRect.top,
          rowRect.right, rowRect.bottom},
        edge);
    }
    if (selected && !armed) {
      nativeUiDrawSelectionArrow(dc,
        rowRect.left + 7,
        rowRect.top +
          std::max(0, static_cast<int>(
            rowRect.bottom - rowRect.top)) / 2,
        selectionArrowColor);
    }
    nativeUiDrawWrappedText(dc, metrics.lines,
      rowRect.left + 19,
      rowRect.top + listLayout.paddingY,
      metrics.labelMaxWidth,
      std::max(1,
        static_cast<int>(rowRect.bottom -
          rowRect.top) -
        listLayout.paddingY * 2),
      listLayout.lineHeight, textColor,
      statusFont);
    RECT hitRect{
      rowRect.left,
      std::max(static_cast<LONG>(
        listHitRect.top), rowRect.top),
      rowRect.right,
      std::min(static_cast<LONG>(
        listHitRect.bottom), rowRect.bottom)};
    if (hitRect.bottom > hitRect.top) {
      rowHits.push_back({hitRect, i});
    }
  }
  nativeUiEndClipRect(dc, clipState);

  if (maxScrollPixels > 0) {
#ifdef __APPLE__
    const int trackW = 18;
    const int minimumThumbH = 28;
    const double thumbScale = 0.72;
#else
    const int trackW = 9;
    const int minimumThumbH = 14;
    const double thumbScale = 0.60;
#endif
    RECT track{listHitRect.right - trackW - 2,
      listHitRect.top + 2,
      listHitRect.right - 2,
      listHitRect.bottom - 2};
#ifdef __APPLE__
    const COLORREF scrollEdge = RGB(148, 112, 15);
#else
    const COLORREF scrollEdge = RGB(74, 82, 89);
#endif
    nativeAppActiveFillOutlinedRect(dc, track,
      RGB(87, 69, 10), scrollEdge);
    const int trackH = std::max(1, static_cast<int>(track.bottom - track.top));
    const int thumbH = std::min(trackH,
      std::max(minimumThumbH,
        static_cast<int>(std::floor(
          trackH *
          (static_cast<double>(visibleRows) /
           std::max(1, virtualRowCount)) *
          thumbScale + 0.5))));
    const int travel = std::max(0, trackH - thumbH);
    const int thumbY = track.top + static_cast<int>(travel *
      (static_cast<double>(scrollPixels) / maxScrollPixels));
    RECT thumb{track.left, thumbY, track.right, thumbY + thumbH};
    nativeAppActiveFillOutlinedRect(dc, thumb,
      nativeUiNamedVisualColor(
        nativeUiVisualPref(visualPrefs,
          "scrollbar_color_mode", "yellow"),
        "yellow"), scrollEdge);
  }
}

static int nativeUiTextWidth(HDC dc, const std::string& text, HFONT font)
{
  if (!dc || text.empty()) return 0;
  const auto cacheKey = std::make_pair(
    reinterpret_cast<uintptr_t>(font), text);
  const auto cached = g_nativeUiTextWidthCache.find(cacheKey);
  if (cached != g_nativeUiTextWidthCache.end()) return cached->second;

  HGDIOBJ oldFont = font ? SelectObject(dc, font) : nullptr;
  int measuredWidth = 0;
#ifdef _WIN32
  SIZE size{0, 0};
  const int required = MultiByteToWideChar(CP_UTF8, 0, text.c_str(), -1, nullptr, 0);
  if (required > 0) {
    std::vector<wchar_t> wide(static_cast<size_t>(required), L'\0');
    MultiByteToWideChar(CP_UTF8, 0, text.c_str(), -1, wide.data(), required);
    GetTextExtentPoint32W(dc, wide.data(), std::max(0, required - 1), &size);
    measuredWidth = static_cast<int>(size.cx);
  }
#else
  RECT measuredRect{0, 0, 0, 0};
  DrawText(dc, text.c_str(), static_cast<int>(text.size()),
    &measuredRect,
    DT_CALCRECT | DT_SINGLELINE | DT_NOPREFIX);
  measuredWidth = static_cast<int>(
    measuredRect.right - measuredRect.left);
#endif
  if (oldFont) SelectObject(dc, oldFont);
  const int width = std::max(0, measuredWidth);
  if (g_nativeUiTextWidthCache.size() >= 8192) {
    g_nativeUiTextWidthCache.clear();
  }
  g_nativeUiTextWidthCache.emplace(cacheKey, width);
  return width;
}

