static int nativeUiVisualPresetIndex(
  const std::map<std::string, std::string>& values)
{
  const auto found = values.find(
    "visual_preset_index");
  return std::max(0, std::min(3,
    found == values.end()
      ? 0 : std::atoi(found->second.c_str())));
}

static std::string nativeUiVisualRawValue(
  const std::map<std::string, std::string>& values,
  const std::string& key)
{
  const auto found = values.find(key);
  if (found != values.end()) return found->second;
  const auto fallback =
    nativeUiVisualDefaults().find(key);
  return fallback == nativeUiVisualDefaults().end()
    ? std::string() : fallback->second;
}

static std::string nativeUiLiveMarkColorMode(
  const std::map<std::string, std::string>& values)
{
  const auto preset = values.find("visual_preset_index");
  const int presetIndex =
    preset == values.end() ? 0 : std::atoi(preset->second.c_str());
  // O preset Padrão é fixo e agora usa cinza, inclusive para instalações que
  // ainda guardaram o antigo vermelho no VISUAL_PREFS_V2.
  if (presetIndex <= 0) return "gray";
  return nativeLower(nativeUiVisualPref(
    values, "live_mark_color_mode", "gray"));
}

static void nativeUiWriteVisualPrefs(
  std::map<std::string, std::string> values)
{
  if (!SetExtState_ptr) return;
  const int active = nativeUiVisualPresetIndex(values);
  values["visual_preset_index"] =
    std::to_string(active);
  values["default_preset_initialized"] = "1";
  for (const auto& key :
       nativeUiVisualPreferenceKeys()) {
    if (values.find(key) == values.end()) {
      values[key] = nativeUiVisualRawValue(values, key);
    }
  }
  if (active > 0) {
    for (const auto& key :
         nativeUiVisualPreferenceKeys()) {
      values["preset" + std::to_string(active) +
        "_" + key] = values[key];
    }
  }

  std::ostringstream encoded;
  encoded << "visual_preset_index=" << active
          << ";default_preset_initialized=1";
  for (const auto& key :
       nativeUiVisualPreferenceKeys()) {
    encoded << ';' << key << '=' << values[key];
  }
  for (int preset = 1; preset <= 3; ++preset) {
    for (const auto& key :
         nativeUiVisualPreferenceKeys()) {
      const std::string presetKey =
        "preset" + std::to_string(preset) +
        "_" + key;
      const auto found = values.find(presetKey);
      encoded << ';' << presetKey << '='
              << (found == values.end()
                    ? nativeUiVisualRawValue(values, key)
                    : found->second);
    }
  }
  SetExtState_ptr(kLuaWindowExtStateSection,
    "VISUAL_PREFS_V2", encoded.str().c_str(), true);

  static const char* barKeys[] = {
    "status_current_top", "status_current_bottom",
    "status_queue_top", "status_queue_bottom",
    "list_current_top", "list_current_bottom",
    "list_queue_top", "list_queue_bottom"
  };
  std::ostringstream bars;
  for (size_t index = 0;
       index < std::size(barKeys); ++index) {
    if (index) bars << ';';
    bars << barKeys[index] << '='
         << values[barKeys[index]];
  }
  SetExtState_ptr(kLuaWindowExtStateSection,
    "BAR_VISIBILITY_V1", bars.str().c_str(), true);
  std::ostringstream statusLayout;
  statusLayout << "current\t"
    << values["status_current_position"]
    << "\nqueue\t"
    << values["status_queue_position"]
    << "\nmultiloop\t"
    << values["status_multiloop_position"];
  SetExtState_ptr(kLuaWindowExtStateSection,
    "STATUS_PANEL_LAYOUT_V1",
    statusLayout.str().c_str(), true);
  SetExtState_ptr(kLuaWindowExtStateSection,
    "RGB_MODE_V1", values["rgb_border_mode"].c_str(), true);
  nativeUiInvalidateVisualPrefsCache();
  // Preferências que também são desenhadas nos apps precisam chegar no
  // bridge no mesmo instante em que mudam na extensão.
  g_nativeForceStateBuild.store(true);

  std::ostringstream listBackgroundPresets;
  std::ostringstream barPresets;
  bool firstList = true;
  bool firstBar = true;
  for (int preset = 1; preset <= 3; ++preset) {
    for (const char* key : {
           "list_current_bg", "list_queue_bg"}) {
      if (!firstList) listBackgroundPresets << ';';
      firstList = false;
      const std::string presetKey =
        "preset" + std::to_string(preset) + "_" + key;
      listBackgroundPresets << presetKey << '='
        << (values.count(presetKey)
              ? values[presetKey]
              : nativeUiVisualRawValue(values, key));
    }
    for (const char* key : barKeys) {
      if (!firstBar) barPresets << ';';
      firstBar = false;
      const std::string presetKey =
        "preset" + std::to_string(preset) + "_" + key;
      barPresets << presetKey << '='
        << (values.count(presetKey)
              ? values[presetKey]
              : nativeUiVisualRawValue(values, key));
    }
  }
  SetExtState_ptr(kLuaWindowExtStateSection,
    "LIST_BG_PRESETS_V1",
    listBackgroundPresets.str().c_str(), true);
  SetExtState_ptr(kLuaWindowExtStateSection,
    "BAR_VISIBILITY_PRESETS_V1",
    barPresets.str().c_str(), true);
  if (UpdateArrange_ptr) UpdateArrange_ptr();
  if (g_nativeAppActivePanelHwnd) {
    InvalidateRect(g_nativeAppActivePanelHwnd,
      nullptr, FALSE);
  }
}

static bool nativeUiSetVisualPreset(int preset)
{
  auto values = nativeUiReadVisualPrefs();
  const int current = nativeUiVisualPresetIndex(values);
  if (current > 0) {
    for (const auto& key :
         nativeUiVisualPreferenceKeys()) {
      values["preset" + std::to_string(current) +
        "_" + key] = nativeUiVisualRawValue(values, key);
    }
  }
  preset = std::max(0, std::min(3, preset));
  values["visual_preset_index"] =
    std::to_string(preset);
  if (preset == 0) {
    for (const auto& entry :
         nativeUiVisualFixedDefaultPreset()) {
      values[entry.first] = entry.second;
    }
  } else {
    for (const auto& key :
         nativeUiVisualPreferenceKeys()) {
      const std::string presetKey =
        "preset" + std::to_string(preset) +
        "_" + key;
      const auto saved = values.find(presetKey);
      values[key] = saved == values.end()
        ? nativeUiVisualDefaults().at(key)
        : saved->second;
    }
  }
  nativeUiWriteVisualPrefs(std::move(values));
  return true;
}

static bool nativeUiSetVisualValue(
  const std::string& key,
  const std::string& value)
{
  auto values = nativeUiReadVisualPrefs();
  const int active = nativeUiVisualPresetIndex(values);
  if (active == 0) return false;
  values[key] = value;
  values["preset" + std::to_string(active) +
    "_" + key] = value;
  nativeUiWriteVisualPrefs(std::move(values));
  return true;
}

static bool nativeUiToggleVisualValue(
  const std::string& key)
{
  const auto values = nativeUiReadVisualPrefs();
  const std::string current = nativeLower(
    nativeUiVisualRawValue(values, key));
  const bool enabled = current == "1" ||
    current == "true" || current == "on" ||
    current == "yes" || current == "sim";
  return nativeUiSetVisualValue(
    key, enabled ? "0" : "1");
}

static std::set<std::string> nativeUiHiddenButtonSet(
  const std::map<std::string, std::string>& values,
  const std::string& rawPage)
{
  const std::string page = rawPage == "regions"
    ? "regions" : "playlist";
  const std::string encoded = nativeUiVisualRawValue(
    values, page + "_hidden_buttons");
  std::set<std::string> result;
  for (const auto& rawId : nativeSplit(encoded, ',')) {
    const std::string id = nativeLower(nativeTrim(rawId));
    if (!id.empty()) result.insert(id);
  }
  return result;
}

static bool nativeUiPageButtonVisible(
  const std::map<std::string, std::string>& values,
  const std::string& page,
  const std::string& rawId)
{
  if (rawId.empty()) return true;
  const std::string id = nativeLower(nativeTrim(rawId));
  if (id == "info_timer") {
    return nativeUiVisualPrefBool(values,
      "info_timer_visible", true);
  }
  if (id == "info_local_time") {
    return nativeUiVisualPrefBool(values,
      "info_local_time_visible", true);
  }
  if (id == "info_battery") {
    return nativeUiVisualPrefBool(values,
      "info_battery_visible", true);
  }
  if (id == "nav_playlist" ||
      id == "nav_regions" ||
      id == "nav_config" ||
      id == "header_update" ||
      (page == "regions" &&
       (id == "action_create" || id == "action_add"))) {
    return true;
  }
  return nativeUiHiddenButtonSet(values, page).count(id) == 0;
}

static bool nativeUiTogglePageButtonVisibility(
  const std::string& rawPage,
  const std::string& rawId)
{
  const std::string page = rawPage == "regions"
    ? "regions" : "playlist";
  const std::string id = nativeLower(nativeTrim(rawId));
  if (id.empty()) return false;
  if (id == "info_timer") {
    return nativeUiToggleVisualValue(
      "info_timer_visible");
  }
  if (id == "info_local_time") {
    return nativeUiToggleVisualValue(
      "info_local_time_visible");
  }
  if (id == "info_battery") {
    return nativeUiToggleVisualValue(
      "info_battery_visible");
  }
  if (id == "nav_playlist" ||
      id == "nav_regions" ||
      id == "nav_config" ||
      id == "header_update" ||
      (page == "regions" &&
       (id == "action_create" || id == "action_add"))) {
    return false;
  }
  auto values = nativeUiReadVisualPrefs();
  if (nativeUiVisualPresetIndex(values) == 0) return false;
  std::set<std::string> hidden =
    nativeUiHiddenButtonSet(values, page);
  if (hidden.count(id)) hidden.erase(id);
  else hidden.insert(id);
  std::ostringstream encoded;
  bool first = true;
  for (const auto& item : hidden) {
    if (!first) encoded << ',';
    first = false;
    encoded << item;
  }
  return nativeUiSetVisualValue(
    page + "_hidden_buttons", encoded.str());
}

