static std::map<std::string, std::vector<std::string>>
nativeUiDefaultButtonLayout(const std::string& rawPage)
{
  const bool regions = rawPage == "regions";
  std::map<std::string, std::vector<std::string>> layout;
  if (regions) {
    layout["top1"] = {
      "nav_playlist", "nav_regions", "nav_mixer",
      "nav_midi", "nav_help", "nav_config"
    };
    layout["top2"] = {
      "action_play", "action_all", "action_create",
      "action_add", "nav_tuner", "action_parts2",
      "action_parts1", "action_timer"
    };
    layout["top3"] = {};
  } else {
    layout["top1"] = {
      "nav_playlist", "nav_regions", "nav_mixer",
      "nav_midi", "nav_config"
    };
    layout["top2"] = {
      "action_loop", "action_atbl", "nav_tuner",
      "action_bypass", "nav_help"
    };
    layout["top3"] = {
      "action_play", "action_auto", "action_auto2",
      "action_blocks", "action_parts2", "action_parts1",
      "action_timer"
    };
  }
  layout["header"] = {
    "header_live", "header_retry", "header_number",
    "header_sort09", "header_update", "header_view"
  };
  if (regions) {
    layout["header"].push_back("header_alpha");
    layout["header"].push_back("header_reset");
  }
  layout["footer"] = {
    "footer_preview_page",
    "footer_preview1", "footer_preview2", "footer_preview3",
    "footer_preview4", "footer_preview5", "footer_preview6",
    "footer_export", "footer_tp1", "footer_tp2", "footer_stop"
  };
  return layout;
}

static std::set<std::string> nativeUiKnownButtonLayoutIds(
  const std::string& rawPage)
{
  std::set<std::string> result;
  const auto defaults = nativeUiDefaultButtonLayout(rawPage);
  for (const auto& zone : defaults) {
    result.insert(zone.second.begin(), zone.second.end());
  }
  return result;
}

static std::map<std::string, std::vector<std::string>>
nativeUiReadButtonLayout(const std::string& rawPage)
{
  const std::string page = rawPage == "regions"
    ? "regions" : "playlist";
  auto result = nativeUiDefaultButtonLayout(page);
  const int preset = nativeUiButtonLayoutActivePreset();
  // O preset Padrao reproduz sempre a composicao oficial e nao aceita
  // sobrescrita de posicao.
  if (preset == 0 || !GetExtState_ptr) return result;
  const std::string storageKey =
    nativeUiButtonLayoutStorageKey(page, preset);
  const char* rawPtr = GetExtState_ptr(
    kLuaWindowExtStateSection,
    storageKey.c_str());
  const std::string raw = rawPtr ? rawPtr : "";
  if (raw.empty()) return result;

  std::map<std::string, std::vector<std::string>> parsed;
  std::set<std::string> seen;
  const std::set<std::string> known =
    nativeUiKnownButtonLayoutIds(page);
  for (const auto& rawZone : nativeSplit(raw, ';')) {
    const size_t separator = rawZone.find('=');
    if (separator == std::string::npos) continue;
    const std::string zone = nativeLower(
      nativeTrim(rawZone.substr(0, separator)));
    if (!nativeUiButtonLayoutZoneValid(zone)) continue;
    for (const auto& rawId :
         nativeSplit(rawZone.substr(separator + 1), ',')) {
      const std::string id = nativeLower(nativeTrim(rawId));
      if (id.empty() || !known.count(id) || seen.count(id)) continue;
      parsed[zone].push_back(id);
      seen.insert(id);
    }
  }
  for (const auto& zone : nativeUiButtonLayoutZones()) {
    if (!parsed.count(zone)) parsed[zone] = {};
  }
  const auto defaults = nativeUiDefaultButtonLayout(page);
  for (const auto& zone : nativeUiButtonLayoutZones()) {
    const auto found = defaults.find(zone);
    if (found == defaults.end()) continue;
    for (const auto& id : found->second) {
      if (seen.insert(id).second) parsed[zone].push_back(id);
    }
  }
  return parsed;
}

static bool nativeUiWriteButtonLayout(
  const std::string& rawPage,
  const std::map<std::string, std::vector<std::string>>& layout)
{
  if (!SetExtState_ptr) return false;
  const std::string page = rawPage == "regions"
    ? "regions" : "playlist";
  const int preset = nativeUiButtonLayoutActivePreset();
  if (preset == 0) return false;
  const std::set<std::string> known =
    nativeUiKnownButtonLayoutIds(page);
  std::set<std::string> seen;
  std::ostringstream encoded;
  bool firstZone = true;
  for (const auto& zone : nativeUiButtonLayoutZones()) {
    if (!firstZone) encoded << ';';
    firstZone = false;
    encoded << zone << '=';
    bool firstId = true;
    const auto found = layout.find(zone);
    if (found == layout.end()) continue;
    for (const auto& rawId : found->second) {
      const std::string id = nativeLower(nativeTrim(rawId));
      if (!known.count(id) || !seen.insert(id).second) continue;
      if (!firstId) encoded << ',';
      firstId = false;
      encoded << id;
    }
  }
  const std::string storageKey =
    nativeUiButtonLayoutStorageKey(page, preset);
  SetExtState_ptr(kLuaWindowExtStateSection,
    storageKey.c_str(),
    encoded.str().c_str(), true);
  return true;
}

static std::vector<std::string> nativeUiButtonIdsForZone(
  const std::string& page,
  const std::string& zone)
{
  const auto layout = nativeUiReadButtonLayout(page);
  const auto found = layout.find(zone);
  return found == layout.end()
    ? std::vector<std::string>{} : found->second;
}

static bool nativeUiMoveButtonLayoutItem(
  const std::string& rawPage,
  const std::string& rawId,
  const std::string& rawZone,
  int rawIndex)
{
  const std::string page = rawPage == "regions"
    ? "regions" : "playlist";
  const std::string id = nativeLower(nativeTrim(rawId));
  const std::string zone = nativeLower(nativeTrim(rawZone));
  if (!nativeUiButtonLayoutZoneValid(zone) ||
      !nativeUiKnownButtonLayoutIds(page).count(id)) {
    return false;
  }
  auto layout = nativeUiReadButtonLayout(page);
  for (auto& item : layout) {
    item.second.erase(std::remove(
      item.second.begin(), item.second.end(), id),
      item.second.end());
  }
  auto& destination = layout[zone];
  const int index = std::max(0, std::min(
    rawIndex, static_cast<int>(destination.size())));
  destination.insert(destination.begin() + index, id);
  return nativeUiWriteButtonLayout(page, layout);
}

static void nativeUiResetButtonLayoutDrag()
{
  g_nativeUiButtonLayoutDrag = NativeUiButtonLayoutDrag{};
}

static bool nativeUiBeginButtonLayoutDrag(const POINT& point)
{
  if (g_nativeMainModalKind !=
      NativeMainModalKind::CustomizeButtonVisibility) {
    return false;
  }
  for (const auto& hit : g_nativeUiButtonLayoutHits) {
    if (!PtInRect(&hit.rect, point)) continue;
    g_nativeUiButtonLayoutDrag.pressed = true;
    g_nativeUiButtonLayoutDrag.pressPoint = point;
    g_nativeUiButtonLayoutDrag.page = hit.page;
    g_nativeUiButtonLayoutDrag.buttonId = hit.buttonId;
    g_nativeUiButtonLayoutDrag.sourceZone = hit.zone;
    g_nativeUiButtonLayoutDrag.sourceIndex = hit.index;
    g_nativeUiButtonLayoutDrag.targetZone = hit.zone;
    g_nativeUiButtonLayoutDrag.targetIndex = hit.index;
    return true;
  }
  return false;
}

static void nativeUiUpdateButtonLayoutDrag(const POINT& point)
{
  if (!g_nativeUiButtonLayoutDrag.pressed) return;
  const int dx = std::abs(
    point.x - g_nativeUiButtonLayoutDrag.pressPoint.x);
  const int dy = std::abs(
    point.y - g_nativeUiButtonLayoutDrag.pressPoint.y);
  if (!g_nativeUiButtonLayoutDrag.active &&
      (dx > 4 || dy > 4)) {
    g_nativeUiButtonLayoutDrag.active = true;
  }
  if (!g_nativeUiButtonLayoutDrag.active) return;

  std::string targetZone;
  for (const auto& zone : g_nativeUiButtonLayoutZoneHits) {
    RECT expanded = zone.rect;
    expanded.top -= 5;
    expanded.bottom += 5;
    if (PtInRect(&expanded, point)) {
      targetZone = zone.zone;
      break;
    }
  }
  if (targetZone.empty()) return;

  std::vector<const NativeUiButtonLayoutHit*> row;
  for (const auto& hit : g_nativeUiButtonLayoutHits) {
    if (hit.zone == targetZone &&
        hit.buttonId != g_nativeUiButtonLayoutDrag.buttonId) {
      row.push_back(&hit);
    }
  }
  std::sort(row.begin(), row.end(),
    [](const NativeUiButtonLayoutHit* left,
       const NativeUiButtonLayoutHit* right) {
      return left->rect.left < right->rect.left;
    });
  int targetIndex = static_cast<int>(row.size());
  for (size_t index = 0; index < row.size(); ++index) {
    const int center = (row[index]->rect.left +
      row[index]->rect.right) / 2;
    if (point.x < center) {
      targetIndex = static_cast<int>(index);
      break;
    }
  }
  g_nativeUiButtonLayoutDrag.targetZone = targetZone;
  g_nativeUiButtonLayoutDrag.targetIndex = targetIndex;
}

static bool nativeUiFinishButtonLayoutDrag()
{
  if (!g_nativeUiButtonLayoutDrag.pressed) return false;
  const NativeUiButtonLayoutDrag drag =
    g_nativeUiButtonLayoutDrag;
  nativeUiResetButtonLayoutDrag();
  if (!drag.active || drag.targetZone.empty() ||
      drag.targetIndex < 0) {
    return false;
  }
  const bool moved = nativeUiMoveButtonLayoutItem(
    drag.page, drag.buttonId,
    drag.targetZone, drag.targetIndex);
  if (!moved && nativeUiButtonLayoutActivePreset() == 0) {
    nativeUiShowTemporaryPopup(
      "O Preset Padrão tem posição fixa. Escolha o Preset 1, 2 ou 3.",
      2.0);
  }
  return moved;
}

