static void nativeUiPollBatteryState()
{
  const auto now = std::chrono::steady_clock::now();
  // No macOS a leitura usa pmset. Quatro segundos mantem a troca visivelmente
  // rapida sem criar processos continuamente; usa o mesmo ritmo no Windows.
  constexpr auto batteryPollInterval = std::chrono::seconds(4);
  if (g_nativeUiBatteryLastPoll.time_since_epoch().count() != 0 &&
      now - g_nativeUiBatteryLastPoll < batteryPollInterval) {
    return;
  }
  g_nativeUiBatteryLastPoll = now;
#ifdef _WIN32
  SYSTEM_POWER_STATUS status{};
  if (!GetSystemPowerStatus(&status) ||
      status.BatteryFlag == 128 ||
      status.BatteryLifePercent == 255) {
    g_nativeUiBatteryPresent = false;
    g_nativeUiBatteryPercent = -1;
    g_nativeUiBatteryCharging = false;
    return;
  }
  g_nativeUiBatteryPresent = true;
  g_nativeUiBatteryPercent = std::max(0,
    std::min(100, static_cast<int>(
      status.BatteryLifePercent)));
  g_nativeUiBatteryCharging =
    (status.BatteryFlag & 8) != 0 ||
    status.ACLineStatus == 1;
#else
  FILE* pipe = popen("pmset -g batt 2>/dev/null", "r");
  if (!pipe) {
    g_nativeUiBatteryPresent = false;
    g_nativeUiBatteryPercent = -1;
    return;
  }
  std::string output;
  char chunk[256]{};
  while (std::fgets(chunk, sizeof(chunk), pipe)) output += chunk;
  pclose(pipe);
  const size_t percentPos = output.find('%');
  if (percentPos == std::string::npos) {
    g_nativeUiBatteryPresent = false;
    g_nativeUiBatteryPercent = -1;
    g_nativeUiBatteryCharging = false;
    return;
  }
  size_t begin = percentPos;
  while (begin > 0 &&
      std::isdigit(static_cast<unsigned char>(output[begin - 1]))) {
    --begin;
  }
  g_nativeUiBatteryPercent = std::max(0, std::min(100,
    std::atoi(output.substr(begin, percentPos - begin).c_str())));
  g_nativeUiBatteryPresent = true;
  const std::string lower = nativeLower(output);
  // "discharging" contém literalmente "charging". A busca antiga, portanto,
  // considerava todo Mac fora da tomada como se ainda estivesse carregando e
  // impedia qualquer aviso de queda de bateria.
  const bool discharging =
    lower.find("discharging") != std::string::npos;
  g_nativeUiBatteryCharging = !discharging && (
    lower.find("; charging;") != std::string::npos ||
    lower.find("; charged;") != std::string::npos ||
    lower.find("ac power") != std::string::npos);
#endif
}

static void nativeUiMaybeWarnBattery(
  const std::map<std::string, std::string>& visual)
{
  if (!nativeUiVisualPrefBool(
        visual, "battery_warning_enabled", true) ||
      !g_nativeUiBatteryPresent ||
      g_nativeUiBatteryPercent < 0 ||
      g_nativeUiBatteryCharging) {
    g_nativeUiBatteryLastWarningBucket = -1;
    return;
  }
  const int threshold = std::max(10, std::min(45,
    std::atoi(nativeUiVisualPref(visual,
      "battery_warning_threshold", "20").c_str())));
  if (g_nativeUiBatteryPercent > threshold) {
    g_nativeUiBatteryLastWarningBucket = -1;
    return;
  }
  // Depois de atingir o limite escolhido, repete o aviso em cada queda real
  // de 1%, sem repetir quando a leitura apenas oscila para cima e volta.
  const int bucket = g_nativeUiBatteryPercent;
  if (g_nativeUiBatteryLastWarningBucket < 0 ||
      bucket < g_nativeUiBatteryLastWarningBucket) {
    g_nativeUiBatteryLastWarningBucket = bucket;
    nativeUiShowBatteryPopup(
      "Bateria em " +
        std::to_string(g_nativeUiBatteryPercent) + "%",
      nativeUiVisualPref(visual,
        "battery_warning_color_mode", "red"));
  }
}

