static void nativeSetPlayProtectionEnabled(bool enabled)
{
  if (SetExtState_ptr) {
    SetExtState_ptr(kLuaWindowExtStateSection,
      kPlayProtectionEnabledKey, enabled ? "1" : "0", true);
  }
  g_nativePlayProtectionLastTapAt =
    std::chrono::steady_clock::time_point();
  g_nativePlayProtectionLastAction.clear();
  nativeBumpManualStopFadeoutRevision();
  g_nativeForceStateBuild.store(true);
}

static bool nativeApplyPlayProtectionCommand(
  const std::string& commandBody)
{
  const std::string type =
    nativeLower(nativeJsonExtractString(commandBody, "type"));
  if (type != "play_protection_set" &&
      type != "play_protection_toggle") {
    return false;
  }
  const bool current = nativePlayProtectionEnabled();
  std::string value =
    nativeJsonExtractString(commandBody, "enabled");
  if (value.empty()) {
    value = nativeJsonExtractString(
      commandBody, "desiredState");
  }
  const bool enabled =
    type == "play_protection_toggle" || value.empty()
      ? !current
      : nativeBoolFromText(value, current);
  nativeSetPlayProtectionEnabled(enabled);
  return true;
}

static bool nativePlayProtectionShouldAllow(
  const std::string& requestedAction)
{
  if (g_nativeManualStopFadeoutBypass ||
      !nativePlayProtectionEnabled()) {
    return true;
  }

  std::string action = requestedAction;
  {
    std::lock_guard<std::mutex> lock(
      g_nativeManualStopFadeoutMutex);
    if (g_nativeManualStopFadeoutRuntime.restorePending) {
      return false;
    }
    if (g_nativeManualStopFadeoutRuntime.active) {
      action = "cancel_stop";
    }
  }
  if (action.empty()) action = "play";

  const auto now = std::chrono::steady_clock::now();
  const bool sameAction =
    g_nativePlayProtectionLastAction == action;
  const bool insideWindow = sameAction &&
    g_nativePlayProtectionLastTapAt.time_since_epoch().count() != 0 &&
    now - g_nativePlayProtectionLastTapAt <=
      std::chrono::milliseconds(550);
  if (insideWindow) {
    g_nativePlayProtectionLastTapAt =
      std::chrono::steady_clock::time_point();
    g_nativePlayProtectionLastAction.clear();
    return true;
  }

  g_nativePlayProtectionLastTapAt = now;
  g_nativePlayProtectionLastAction = action;
  std::string label = "Play";
  if (action == "stop") label = "Parar";
  else if (action == "cancel_stop") label = "Cancelar Stop";
  nativeUiShowTemporaryPopup("Toque 2x para " + label, 0.8);
  return false;
}

