static int nativeUiManualStopSelectedCount()
{
  const auto selected = nativeManualStopFadeoutTrackIds();
  int count = 0;
  for (const auto& row : g_nativeUiManualStopTracks) {
    if (std::find(selected.begin(), selected.end(), row.guid) !=
        selected.end()) {
      ++count;
    }
  }
  return count;
}

