static COLORREF nativeUiBlendColor(
  COLORREF background,
  COLORREF foreground,
  double alpha)
{
  alpha = std::max(0.0, std::min(1.0, alpha));
  const auto blend = [alpha](int back, int front) {
    return static_cast<int>(std::floor(
      back * (1.0 - alpha) +
      front * alpha + 0.5));
  };
  return RGB(
    blend(GetRValue(background),
      GetRValue(foreground)),
    blend(GetGValue(background),
      GetGValue(foreground)),
    blend(GetBValue(background),
      GetBValue(foreground)));
}

static NativeUiListLayout nativeUiCurrentListLayout(
  const std::map<std::string, std::string>& visualPrefs)
{
  NativeUiListLayout layout;
  const std::string mode = nativeLower(
    nativeUiVisualPref(visualPrefs, "list_scale_mode", "normal"));
#ifdef __APPLE__
  // Mesmas medidas derivadas de row_h=22 usadas pelo Lua no macOS.
  if (mode == "large") {
    layout.baseHeight = 27;
    layout.paddingY = 4;
    layout.lineHeight = 23;
  } else if (mode == "normal") {
    layout.baseHeight = 22;
    layout.paddingY = 3;
    layout.lineHeight = 18;
  } else {
    layout.baseHeight = 18;
    layout.paddingY = 2;
    layout.lineHeight = 16;
  }
#else
  // Mesmas medidas derivadas de row_h=18 usadas pelo Lua no Windows.
  if (mode == "large") {
    layout.baseHeight = 23;
    layout.paddingY = 4;
    layout.lineHeight = 19;
  } else if (mode == "normal") {
    layout.baseHeight = 18;
    layout.paddingY = 3;
    layout.lineHeight = 14;
  } else {
    layout.baseHeight = 14;
    layout.paddingY = 2;
    layout.lineHeight = 12;
  }
#endif
  layout.singleRowHeight = std::max(
    layout.baseHeight - 1,
    layout.lineHeight + layout.paddingY * 2);
  return layout;
}

static size_t nativeUiNextUtf8Byte(
  const std::string& value,
  size_t index)
{
  if (index >= value.size()) return value.size();
  const unsigned char first =
    static_cast<unsigned char>(value[index]);
  size_t width = 1;
  if ((first & 0xf8) == 0xf0) width = 4;
  else if ((first & 0xf0) == 0xe0) width = 3;
  else if ((first & 0xe0) == 0xc0) width = 2;
  return std::min(value.size(), index + width);
}

static std::vector<std::string> nativeUiWrapText(
  HDC dc,
  const std::string& text,
  int maxWidth,
  HFONT font)
{
  if (text.empty()) return {std::string()};
  if (maxWidth <= 8) return {text};

  std::string normalized;
  normalized.reserve(text.size());
  for (size_t i = 0; i < text.size(); ++i) {
    if (text[i] == '\r') {
      if (i + 1 < text.size() && text[i + 1] == '\n') continue;
      normalized.push_back('\n');
    } else {
      normalized.push_back(text[i]);
    }
  }

  std::vector<std::string> lines;
  size_t paragraphStart = 0;
  while (paragraphStart <= normalized.size()) {
    size_t paragraphEnd =
      normalized.find('\n', paragraphStart);
    if (paragraphEnd == std::string::npos) {
      paragraphEnd = normalized.size();
    }
    const std::string paragraph =
      normalized.substr(paragraphStart,
        paragraphEnd - paragraphStart);
    std::istringstream words(paragraph);
    std::string current;
    std::string word;
    bool hadWord = false;
    while (words >> word) {
      hadWord = true;
      const std::string candidate =
        current.empty() ? word : current + " " + word;
      if (nativeUiTextWidth(dc, candidate, font) <= maxWidth) {
        current = candidate;
        continue;
      }
      if (!current.empty()) {
        lines.push_back(current);
        current.clear();
      }
      if (nativeUiTextWidth(dc, word, font) <= maxWidth) {
        current = word;
        continue;
      }
      std::string piece;
      size_t byte = 0;
      while (byte < word.size()) {
        const size_t next = nativeUiNextUtf8Byte(word, byte);
        const std::string glyph = word.substr(byte, next - byte);
        const std::string test = piece + glyph;
        if (!piece.empty() &&
            nativeUiTextWidth(dc, test, font) > maxWidth) {
          lines.push_back(piece);
          piece = glyph;
        } else {
          piece = test;
        }
        byte = next;
      }
      current = piece;
    }
    if (!current.empty()) {
      lines.push_back(current);
    } else if (!hadWord) {
      lines.push_back(std::string());
    }
    if (paragraphEnd >= normalized.size()) break;
    paragraphStart = paragraphEnd + 1;
  }
  if (lines.empty()) lines.push_back(text);
  return lines;
}

static std::string nativeUiFitBlockLabelBeforeWrap(
  HDC dc,
  const std::string& value,
  int maxWidth,
  HFONT font)
{
  if (value.empty() || maxWidth <= 8 ||
      value.find("BLOCO") == std::string::npos ||
      nativeUiTextWidth(dc, value, font) <= maxWidth) {
    return value;
  }

  size_t firstName = value.find("BLOCO");
  if (firstName == std::string::npos) return value;
  size_t leftEnd = firstName;
  while (leftEnd > 0 &&
         std::isspace(static_cast<unsigned char>(
           value[leftEnd - 1]))) {
    --leftEnd;
  }
  std::string leftMarks = value.substr(0, leftEnd);
  if (leftMarks.empty() ||
      leftMarks.find_first_not_of(":=>") != std::string::npos) {
    return value;
  }

  size_t rightStart = value.size();
  while (rightStart > firstName &&
         std::isspace(static_cast<unsigned char>(
           value[rightStart - 1]))) {
    --rightStart;
  }
  size_t marksStart = rightStart;
  while (marksStart > firstName) {
    const char c = value[marksStart - 1];
    if (c != ':' && c != '=' && c != '<') break;
    --marksStart;
  }
  if (marksStart == rightStart) return value;
  const std::string fixedName =
    nativeTrim(value.substr(firstName,
      marksStart - firstName));
  const std::string rightMarks =
    value.substr(marksStart, rightStart - marksStart);
  const char leftChar = leftMarks.empty() ? ':' : leftMarks.front();
  const char rightChar =
    rightMarks.empty() ? ':' : rightMarks.front();

  for (int rightCount =
         static_cast<int>(rightMarks.size());
       rightCount >= 0; --rightCount) {
    std::string candidate(
      leftMarks.size(), leftChar);
    candidate += " " + fixedName;
    if (rightCount > 0) {
      candidate += " " +
        std::string(static_cast<size_t>(rightCount),
          rightChar);
    }
    if (nativeUiTextWidth(dc, candidate, font) <=
        maxWidth) {
      return candidate;
    }
  }
  for (int leftCount =
         static_cast<int>(leftMarks.size()) - 1;
       leftCount >= 0; --leftCount) {
    std::string candidate;
    if (leftCount > 0) {
      candidate =
        std::string(static_cast<size_t>(leftCount),
          leftChar) + " ";
    }
    candidate += fixedName;
    if (nativeUiTextWidth(dc, candidate, font) <=
        maxWidth) {
      return candidate;
    }
  }
  return fixedName;
}

struct NativeUiMainRowMetrics {
  int height = 16;
  int labelMaxWidth = 20;
  int timeWidth = 0;
  std::string label;
  std::string timeText;
  std::vector<std::string> lines;
};

static NativeUiMainRowMetrics nativeUiMeasureMainRow(
  HDC dc,
  const NativeAppActivePanelModel::Row& row,
  int baseWidth,
  bool isPlaying,
  bool familyControlVisible,
  bool liveResetVisible,
  HFONT font,
  const NativeUiListLayout& layout)
{
  NativeUiMainRowMetrics metrics;
  metrics.label = row.name;
  double duration = row.block
    ? std::max(0.0, row.blockDurationSec)
    : std::max(0.0, row.end - row.start);
  if (!row.block &&
      isPlaying &&
      g_nativeAppActivePanelModel.playing) {
    // Para uma regiao pai, o progresso publicado pertence normalmente a uma
    // filha. Multiplicar o tempo total do pai por esse progresso produz uma
    // contagem incorreta. A posicao absoluta funciona tanto no pai quanto em
    // uma regiao comum.
    const bool playPositionInside =
      g_nativeCurrentPlayPosition >= row.start - 0.0005 &&
      g_nativeCurrentPlayPosition < row.end + 0.0005;
    if (playPositionInside) {
      duration = std::max(0.0,
        row.end - g_nativeCurrentPlayPosition);
    } else {
      duration *= std::max(0.0,
        std::min(1.0,
          1.0 -
            g_nativeAppActivePanelModel.progress));
    }
  }
  metrics.timeText =
    nativeAppActiveFormatDuration(duration);
  metrics.timeWidth = metrics.timeText.empty()
    ? 0
    : nativeUiTextWidth(dc, metrics.timeText, font);
  const int childIndent = row.child ? 12 : 0;
  const int labelStartOffset = 28 + 7 + childIndent;
  int rightPadding = metrics.timeText.empty()
    ? 11
    : metrics.timeWidth + 14;
  if (familyControlVisible) {
#ifdef __APPLE__
    rightPadding += 74;
#else
    rightPadding += 68;
#endif
  }
  if (liveResetVisible) {
    rightPadding += 26;
  }
  metrics.labelMaxWidth = std::max(
    20, baseWidth - labelStartOffset -
      rightPadding);
  if (row.block) {
    metrics.label = nativeUiFitBlockLabelBeforeWrap(
      dc, metrics.label, metrics.labelMaxWidth, font);
  }
  metrics.lines = nativeUiWrapText(dc, metrics.label,
    metrics.labelMaxWidth, font);
  metrics.height = std::max(
    layout.baseHeight - 1,
    static_cast<int>(metrics.lines.size()) *
        layout.lineHeight +
      layout.paddingY * 2);
  return metrics;
}

static void nativeUiDrawWrappedText(
  HDC dc,
  const std::vector<std::string>& lines,
  int x,
  int y,
  int width,
  int height,
  int lineHeight,
  COLORREF color,
  HFONT font)
{
  const int maxLines = std::max(
    1, height / std::max(1, lineHeight));
  const int drawCount = std::min(
    static_cast<int>(lines.size()), maxLines);
  for (int index = 0; index < drawCount; ++index) {
    RECT lineRect{x,
      y + index * lineHeight,
      x + width,
      y + (index + 1) * lineHeight};
    nativeAppActiveDrawText(dc, lines[
      static_cast<size_t>(index)], lineRect,
      DT_LEFT | DT_TOP | DT_SINGLELINE |
        DT_NOPREFIX | DT_NOCLIP,
      color, font);
  }
}

static NativeUiPartsRowMetrics nativeUiMeasurePartsRow(
  HDC dc,
  const NativeAppActivePanelModel::PartRow& row,
  int baseWidth,
  HFONT font,
  const NativeUiListLayout& layout)
{
  NativeUiPartsRowMetrics metrics;
  metrics.label = row.name == "sem nome"
    ? row.name
    : nativeUpperNamePtBrKeepParentheses(
        row.name);
  // Parts não possui coluna numérica. O primeiro gutter de 12 px é
  // reservado para o ">" de engatilhamento, exatamente como no Lua.
  const int labelStartOffset = 7 + 12;
  metrics.labelMaxWidth = std::max(
    20, baseWidth - labelStartOffset - 11);
  metrics.lines = nativeUiWrapText(dc,
    metrics.label, metrics.labelMaxWidth, font);
  metrics.height = std::max(
    layout.baseHeight - 1,
    static_cast<int>(metrics.lines.size()) *
        layout.lineHeight +
      layout.paddingY * 2);
  return metrics;
}

static bool nativeUiSearchMatches(
  const NativeAppActivePanelModel::Row& row,
  const std::string& query)
{
  if (query.empty()) return true;
  const std::string wanted = nativeLower(nativeTrim(query));
  if (wanted.empty()) return true;
  const std::string name = nativeLower(row.name);
  if (name.find(wanted) != std::string::npos) return true;
  const int visibleColumnNumber =
    g_nativeAppActivePanelModel.numberRegionMode
      ? std::abs(row.sourceNumber)
      : std::max(0, row.displayNumber);
  if (visibleColumnNumber > 0 &&
      std::to_string(visibleColumnNumber).find(wanted) !=
        std::string::npos) {
    return true;
  }
  return false;
}

static bool nativeUiSearchMatchesSong(
  const NativeSongWindow& song,
  const std::string& query,
  int visibleColumnNumber = 0)
{
  if (song.isBlock) return false;
  const std::string wanted = nativeLower(nativeTrim(query));
  if (wanted.empty()) return true;
  const std::string name = nativeLower(
    nativeUpperNamePtBrKeepParentheses(
      nativeCleanSongName(song.name)));
  if (name.find(wanted) != std::string::npos) return true;
  const int columnNumber =
    g_nativeAppActivePanelModel.numberRegionMode
      ? std::abs(song.sourceNumber)
      : std::max(0, visibleColumnNumber);
  return columnNumber > 0 &&
    std::to_string(columnNumber).find(wanted) !=
      std::string::npos;
}

static std::vector<size_t> nativeUiBuildVisibleRowIndices()
{
  std::vector<size_t> indices;
  indices.reserve(g_nativeAppActivePanelModel.rows.size());
  for (size_t i = 0; i < g_nativeAppActivePanelModel.rows.size(); ++i) {
    if (nativeUiSearchMatches(
          g_nativeAppActivePanelModel.rows[i],
          g_nativeMainSearchAppliedText)) {
      indices.push_back(i);
    }
  }

  if (g_nativeAppActivePanelModel.regionsPage && g_nativeRegionsSortMode != 0) {
    const int mode = g_nativeRegionsSortMode;
    std::map<std::string,
      const NativeAppActivePanelModel::Row*> familyParents;
    for (const auto& row : g_nativeAppActivePanelModel.rows) {
      if (row.familyParent && !row.id.empty()) {
        familyParents[row.id] = &row;
      }
    }
    const auto familyAnchor = [&](size_t rowIndex) {
      const auto& row =
        g_nativeAppActivePanelModel.rows[rowIndex];
      if (row.child && !row.parentId.empty()) {
        const auto found = familyParents.find(row.parentId);
        if (found != familyParents.end()) return found->second;
      }
      return &row;
    };
    std::stable_sort(indices.begin(), indices.end(), [mode, &familyAnchor](size_t leftIndex, size_t rightIndex) {
      const auto& left = g_nativeAppActivePanelModel.rows[leftIndex];
      const auto& right = g_nativeAppActivePanelModel.rows[rightIndex];
      const auto* leftAnchor = familyAnchor(leftIndex);
      const auto* rightAnchor = familyAnchor(rightIndex);
      // Pai e filhos são uma unidade também quando Number/0-9 reordena a
      // aba. Dentro da família permanece sempre pai -> filhos.
      if (leftAnchor == rightAnchor) {
        return left.order < right.order;
      }
      if (mode == 1 || mode == 2) {
        const std::string leftName =
          nativeLower(leftAnchor->name);
        const std::string rightName =
          nativeLower(rightAnchor->name);
        if (leftName == rightName) {
          return leftAnchor->order < rightAnchor->order;
        }
        return mode == 2 ? leftName > rightName : leftName < rightName;
      }
      const int leftNumber =
        std::abs(leftAnchor->sourceNumber);
      const int rightNumber =
        std::abs(rightAnchor->sourceNumber);
      if (leftNumber == rightNumber) {
        return leftAnchor->order < rightAnchor->order;
      }
      return mode == 4 ? leftNumber > rightNumber : leftNumber < rightNumber;
    });
  }
  return indices;
}

static std::string nativeUiMainRowKey(
  const NativeAppActivePanelModel::Row& row,
  bool regionsPage)
{
  std::ostringstream key;
  key << (regionsPage ? "regions|" : "playlist|")
      << row.id << "|" << row.order << "|"
      << std::fixed << std::setprecision(6)
      << row.start << "|" << row.end;
  return key.str();
}

static bool nativeUiMainRowIsSelected(
  const NativeAppActivePanelModel::Row& row,
  bool regionsPage)
{
  const auto found =
    g_nativeUiSelectedRows.find(nativeUiMainRowKey(row, regionsPage));
  return found != g_nativeUiSelectedRows.end() && found->second;
}

static void nativeUiRemoveSelectionOrderKey(const std::string& key)
{
  g_nativeUiSelectionOrder.erase(
    std::remove(g_nativeUiSelectionOrder.begin(),
      g_nativeUiSelectionOrder.end(), key),
    g_nativeUiSelectionOrder.end());
}

static void nativeUiSetMainRowSelected(
  const NativeAppActivePanelModel::Row& row,
  bool regionsPage,
  bool selected)
{
  // Tambem vale para selected=false: desmarcar a ultima linha e um estado
  // visual deliberado e nao deve ressuscitar a selecao antiga do motor.
  g_nativeUiMainSelectionAuthoritative = true;
  const std::string key = nativeUiMainRowKey(row, regionsPage);
  nativeUiRemoveSelectionOrderKey(key);
  if (selected) {
    g_nativeUiSelectedRows[key] = true;
    g_nativeUiSelectionOrder.push_back(key);
  } else {
    g_nativeUiSelectedRows.erase(key);
  }
}

static void nativeUiClearMainRowSelection()
{
  g_nativeUiSelectedRows.clear();
  g_nativeUiSelectionOrder.clear();
  g_nativeUiSelectionAnchorVisibleIndex = -1;
  g_nativeUiSelectionFocusVisibleIndex = -1;
  g_nativeUiMainSelectionAuthoritative = false;
  g_nativeUiMusicSelectionVisualActive = false;
}

static void nativeUiClearMainRowSelectionForPage(bool regionsPage)
{
  const std::string prefix = regionsPage ? "regions|" : "playlist|";
  for (auto it = g_nativeUiSelectedRows.begin();
       it != g_nativeUiSelectedRows.end();) {
    if (it->first.rfind(prefix, 0) == 0) {
      it = g_nativeUiSelectedRows.erase(it);
    } else {
      ++it;
    }
  }
  g_nativeUiSelectionOrder.erase(
    std::remove_if(g_nativeUiSelectionOrder.begin(),
      g_nativeUiSelectionOrder.end(),
      [&](const std::string& key) {
        return key.rfind(prefix, 0) == 0;
      }),
    g_nativeUiSelectionOrder.end());
  g_nativeUiSelectionAnchorVisibleIndex = -1;
  g_nativeUiSelectionFocusVisibleIndex = -1;
  g_nativeUiMainSelectionAuthoritative = false;
  g_nativeUiMusicSelectionVisualActive = false;
}

static int nativeUiMainSelectionCount(bool regionsPage)
{
  const std::string prefix = regionsPage ? "regions|" : "playlist|";
  int count = 0;
  for (const auto& entry : g_nativeUiSelectedRows) {
    if (entry.second && entry.first.rfind(prefix, 0) == 0) ++count;
  }
  return count;
}

static const NativeAppActivePanelModel::Row* nativeUiFindModelRowByKey(
  const std::string& key,
  bool regionsPage)
{
  for (const auto& row : g_nativeAppActivePanelModel.rows) {
    if (nativeUiMainRowKey(row, regionsPage) == key) return &row;
  }
  return nullptr;
}

static std::vector<const NativeAppActivePanelModel::Row*>
nativeUiSelectedModelRows(bool regionsPage, bool includeBlocks = false)
{
  std::vector<const NativeAppActivePanelModel::Row*> rows;
  std::map<std::string, bool> emitted;
  for (const std::string& key : g_nativeUiSelectionOrder) {
    const auto found = g_nativeUiSelectedRows.find(key);
    if (found == g_nativeUiSelectedRows.end() || !found->second) continue;
    const auto* row = nativeUiFindModelRowByKey(key, regionsPage);
    if (!row || (!includeBlocks && row->block)) continue;
    rows.push_back(row);
    emitted[key] = true;
  }
  for (const auto& row : g_nativeAppActivePanelModel.rows) {
    if (!includeBlocks && row.block) continue;
    const std::string key = nativeUiMainRowKey(row, regionsPage);
    const auto selected = g_nativeUiSelectedRows.find(key);
    if (selected == g_nativeUiSelectedRows.end() || !selected->second ||
        emitted.find(key) != emitted.end()) {
      continue;
    }
    rows.push_back(&row);
  }
  return rows;
}

static std::string nativeUiMainRowStableIdentity(
  const NativeAppActivePanelModel::Row& row)
{
  std::ostringstream key;
  key << (row.block ? "block|" : "song|")
      << row.id << "|" << row.sourceNumber << "|"
      << std::fixed << std::setprecision(6)
      << row.start << "|" << row.end << "|" << row.name;
  return key.str();
}

struct NativeUiReorderFamilyInfo {
  bool parent = false;
  bool child = false;
  std::string key;
};

static NativeUiReorderFamilyInfo nativeUiPlaylistLineFamilyInfo(
  const std::string& line)
{
  NativeUiReorderFamilyInfo info;
  const auto fields = nativeSplit(line, '\t');
  if (fields.empty() || fields[0] != "ITEM") return info;
  info.parent = fields.size() > 8 && fields[8] == "1";
  info.child = fields.size() > 9 && fields[9] == "1";
  if (info.parent && fields.size() > 2) {
    info.key = fields[2];
  } else if (info.child && fields.size() > 12) {
    info.key = fields[12];
  }
  return info;
}

static NativeUiReorderFamilyInfo nativeUiSongFamilyInfo(
  const NativeSongWindow& song)
{
  NativeUiReorderFamilyInfo info;
  info.parent = song.isHashParent;
  info.child = song.isHashChild || song.isRegionChild;
  info.key = info.parent ? song.id : (info.child ? song.parentId : "");
  return info;
}

static NativeUiReorderFamilyInfo nativeUiModelRowFamilyInfo(
  const NativeAppActivePanelModel::Row& row)
{
  NativeUiReorderFamilyInfo info;
  info.parent = row.familyParent;
  info.child = row.child || row.markerChild;
  info.key = info.parent ? row.id : (info.child ? row.parentId : "");
  return info;
}

template <typename T, typename FamilyInfoFn>
static void nativeUiExpandSelectedFamilyParents(
  const std::vector<T>& items,
  std::vector<bool>& selected,
  FamilyInfoFn familyInfo)
{
  if (selected.size() != items.size()) return;
  for (size_t index = 0; index < items.size(); ++index) {
    if (!selected[index]) continue;
    const NativeUiReorderFamilyInfo parent = familyInfo(items[index]);
    if (!parent.parent || parent.key.empty()) continue;
    for (size_t childIndex = index + 1;
         childIndex < items.size(); ++childIndex) {
      const NativeUiReorderFamilyInfo child = familyInfo(items[childIndex]);
      if (!child.child || child.key != parent.key) break;
      selected[childIndex] = true;
    }
  }
}

template <typename T, typename FamilyInfoFn>
static int nativeUiClampFamilyReorderTarget(
  const std::vector<T>& items,
  const std::vector<bool>& selected,
  int targetIndex,
  FamilyInfoFn familyInfo)
{
  targetIndex = std::max(0,
    std::min(targetIndex, static_cast<int>(items.size())));
  size_t index = 0;
  while (index < items.size()) {
    const NativeUiReorderFamilyInfo item = familyInfo(items[index]);
    if (item.child && !item.key.empty() &&
        (index >= selected.size() || !selected[index])) {
      size_t first = index;
      size_t last = index;
      while (first > 0) {
        const NativeUiReorderFamilyInfo previous =
          familyInfo(items[first - 1]);
        if ((!previous.parent && !previous.child) ||
            previous.key != item.key) {
          break;
        }
        --first;
      }
      while (last + 1 < items.size()) {
        const NativeUiReorderFamilyInfo next =
          familyInfo(items[last + 1]);
        if ((!next.parent && !next.child) || next.key != item.key) break;
        ++last;
      }
      if (targetIndex > static_cast<int>(first) &&
          targetIndex <= static_cast<int>(last)) {
        return static_cast<int>(last) + 1;
      }
      index = last + 1;
    } else {
      ++index;
    }
  }
  return targetIndex;
}

template <typename T, typename FamilyInfoFn>
static std::vector<T> nativeUiNormalizeFamilyOrder(
  const std::vector<T>& items,
  FamilyInfoFn familyInfo)
{
  std::map<std::string, std::vector<T>> childrenByKey;
  std::vector<std::string> childKeyOrder;
  std::vector<T> base;
  base.reserve(items.size());
  for (const auto& item : items) {
    const NativeUiReorderFamilyInfo info = familyInfo(item);
    if (info.child && !info.key.empty()) {
      if (childrenByKey.find(info.key) == childrenByKey.end()) {
        childKeyOrder.push_back(info.key);
      }
      childrenByKey[info.key].push_back(item);
    } else {
      base.push_back(item);
    }
  }

  std::vector<T> result;
  result.reserve(items.size());
  for (const auto& item : base) {
    result.push_back(item);
    const NativeUiReorderFamilyInfo info = familyInfo(item);
    if (!info.parent || info.key.empty()) continue;
    const auto found = childrenByKey.find(info.key);
    if (found == childrenByKey.end()) continue;
    result.insert(result.end(), found->second.begin(), found->second.end());
    childrenByKey.erase(found);
  }
  for (const std::string& key : childKeyOrder) {
    const auto found = childrenByKey.find(key);
    if (found == childrenByKey.end()) continue;
    result.insert(result.end(), found->second.begin(), found->second.end());
    childrenByKey.erase(found);
  }
  return result;
}

template <typename T>
static std::vector<T> nativeUiMoveSelectedItems(
  const std::vector<T>& items,
  const std::vector<bool>& selected,
  int targetIndex)
{
  if (items.empty() || selected.size() != items.size()) return items;
  targetIndex = std::max(0,
    std::min(targetIndex, static_cast<int>(items.size())));
  int selectedBeforeTarget = 0;
  for (int index = 0; index < targetIndex; ++index) {
    if (selected[static_cast<size_t>(index)]) ++selectedBeforeTarget;
  }
  int insertion = targetIndex - selectedBeforeTarget;

  std::vector<T> moving;
  std::vector<T> remaining;
  moving.reserve(items.size());
  remaining.reserve(items.size());
  for (size_t index = 0; index < items.size(); ++index) {
    if (selected[index]) moving.push_back(items[index]);
    else remaining.push_back(items[index]);
  }
  insertion = std::max(0,
    std::min(insertion, static_cast<int>(remaining.size())));
  remaining.insert(
    remaining.begin() + static_cast<std::ptrdiff_t>(insertion),
    moving.begin(), moving.end());
  return remaining;
}

static int nativeUiMainDragTargetModelIndex(int targetVisibleIndex)
{
  if (g_nativeMainVisibleRowIndices.empty()) return 0;
  if (targetVisibleIndex <= 0) {
    return static_cast<int>(g_nativeMainVisibleRowIndices.front());
  }
  if (targetVisibleIndex >=
      static_cast<int>(g_nativeMainVisibleRowIndices.size())) {
    return static_cast<int>(g_nativeMainVisibleRowIndices.back()) + 1;
  }
  return static_cast<int>(g_nativeMainVisibleRowIndices[
    static_cast<size_t>(targetVisibleIndex)]);
}

static void nativeUiRestoreSelectionAfterMainReorder(
  const std::map<std::string, bool>& selectedIdentities,
  bool regionsPage)
{
  nativeUiClearMainRowSelectionForPage(regionsPage);
  int firstVisible = -1;
  int lastVisible = -1;
  for (size_t index = 0;
       index < g_nativeAppActivePanelModel.rows.size(); ++index) {
    const auto& row = g_nativeAppActivePanelModel.rows[index];
    if (selectedIdentities.find(
          nativeUiMainRowStableIdentity(row)) ==
        selectedIdentities.end()) {
      continue;
    }
    nativeUiSetMainRowSelected(row, regionsPage, true);
    for (size_t visible = 0;
         visible < g_nativeMainVisibleRowIndices.size(); ++visible) {
      if (g_nativeMainVisibleRowIndices[visible] != index) continue;
      if (firstVisible < 0) firstVisible = static_cast<int>(visible);
      lastVisible = static_cast<int>(visible);
      break;
    }
  }
  g_nativeUiSelectionAnchorVisibleIndex = firstVisible;
  g_nativeUiSelectionFocusVisibleIndex =
    lastVisible >= 0 ? lastVisible : firstVisible;
}

static void nativeUiApplyPendingDropSelectionToCurrentModel()
{
  if (g_nativeMainPendingDropSelectionIdentities.empty() ||
      g_nativeAppActivePanelModel.regionsPage !=
        g_nativeMainPendingDropSelectionRegionsPage ||
      g_nativeAppActivePanelModel.mixerPage) {
    return;
  }
  g_nativeMainVisibleRowIndices = nativeUiBuildVisibleRowIndices();
  nativeUiRestoreSelectionAfterMainReorder(
    g_nativeMainPendingDropSelectionIdentities,
    g_nativeMainPendingDropSelectionRegionsPage);
  g_nativeMainPendingDropSelectionIdentities.clear();
}

static void nativeUiSynchronizePlaylistSourceAfterDrop(
  ReaProject* project)
{
  if (!project) return;
  std::vector<NativeSongWindow> songs;
  {
    std::lock_guard<std::mutex> lock(g_nativeMutex);
    songs = g_nativeSongWindows;
  }

  int activePlaylistIndex = 0;
  std::string activePlaylistName;
  std::vector<NativeSongWindow> activeItems;
  double activeTotal = 0.0;
  // Rele exatamente a fonte persistida. O drop nao reordena um segundo vetor
  // visual em paralelo: a proxima montagem nasce desta unica fonte canonica.
  nativeBuildPlaylistsJson(project, songs,
    activePlaylistIndex, activePlaylistName,
    &activeItems, &activeTotal);
  {
    std::lock_guard<std::mutex> lock(g_nativeMutex);
    g_nativeActivePlaylistItems = activeItems;
  }
  g_nativeUiRowsSourceSignatureValid = false;
}

static int nativeUiPlaylistLineIndexForRow(
  const std::vector<std::string>& itemLines,
  const NativeAppActivePanelModel::Row& row,
  const std::vector<bool>* claimed = nullptr)
{
  const int expectedIndex = std::max(0, row.order - 1);
  int bestIndex = -1;
  int bestScore = std::numeric_limits<int>::max();
  const std::string wantedName =
    nativeUpperNamePtBrKeepParentheses(nativeTrim(row.name));

  for (size_t index = 0; index < itemLines.size(); ++index) {
    if (claimed && index < claimed->size() &&
        (*claimed)[index]) {
      continue;
    }
    const auto fields = nativeSplit(itemLines[index], '\t');
    if (fields.size() < 3 || fields[0] != "ITEM") continue;

    const int storedSourceNumber =
      std::atoi(fields[2].c_str());
    const bool storedBlock =
      (fields.size() > 1 && fields[1] == "block") ||
      storedSourceNumber < 0;
    if (storedBlock != row.block) continue;

    const int distance =
      std::abs(static_cast<int>(index) - expectedIndex);
    int score = std::numeric_limits<int>::max();
    const std::string storedName = fields.size() > 5
      ? nativeUpperNamePtBrKeepParentheses(
          nativeTrim(nativeUnescapeExtField(fields[5])))
      : std::string();

    if (storedBlock) {
      if (storedSourceNumber != 0 &&
          storedSourceNumber == row.sourceNumber) {
        score = distance;
      } else if (!wantedName.empty() &&
                 storedName == wantedName) {
        score = 1000 + distance;
      }
    } else {
      const bool storedChild =
        fields.size() > 9 && fields[9] == "1";
      const int storedMarkerNumber =
        fields.size() > 10
          ? std::atoi(fields[10].c_str())
          : 0;
      const int effectiveSourceNumber =
        storedChild && storedMarkerNumber != 0
          ? storedMarkerNumber
          : storedSourceNumber;
      const double storedStart =
        fields.size() > 3
          ? std::atof(fields[3].c_str())
          : 0.0;
      const double storedEnd =
        fields.size() > 4
          ? std::atof(fields[4].c_str())
          : 0.0;
      const bool sourceMatches =
        effectiveSourceNumber == row.sourceNumber ||
        (!row.id.empty() &&
         row.id == std::to_string(effectiveSourceNumber));
      const bool boundsMatch =
        std::fabs(storedStart - row.start) <= 0.003 &&
        std::fabs(storedEnd - row.end) <= 0.003;
      const bool nameMatches =
        !wantedName.empty() && storedName == wantedName;

      if (sourceMatches && boundsMatch) {
        score = distance;
      } else if (sourceMatches) {
        score = 2000 + distance;
      } else if (boundsMatch && nameMatches) {
        score = 4000 + distance;
      } else if (nameMatches) {
        score = 6000 + distance;
      }
    }

    if (score < bestScore) {
      bestScore = score;
      bestIndex = static_cast<int>(index);
    }
  }
  return bestIndex;
}

static bool nativeUiReorderPlaylistRows(
  int sourceModelIndex,
  int targetModelIndex)
{
  char pathBuf[2048] = "";
  ReaProject* project = getCurrentProject(
    pathBuf, static_cast<int>(sizeof(pathBuf)));
  if (!project) return false;
  auto playlists = nativeUiReadPlaylistRecords(project);
  const int playlistIndex =
    nativeUiCurrentPlaylistIndex(project, playlists);
  if (playlistIndex < 0 || playlistIndex >=
      static_cast<int>(playlists.size())) {
    return false;
  }
  auto& itemLines = playlists[static_cast<size_t>(playlistIndex)].itemLines;
  if (itemLines.empty() || sourceModelIndex < 0 ||
      sourceModelIndex >= static_cast<int>(
        g_nativeAppActivePanelModel.rows.size())) {
    return false;
  }

  std::vector<bool> selected(itemLines.size(), false);
  std::vector<bool> claimed(itemLines.size(), false);
  std::map<std::string, bool> selectedIdentities;
  const auto selectedRows = nativeUiSelectedModelRows(false, true);
  for (const auto* row : selectedRows) {
    if (!row) continue;
    selectedIdentities[nativeUiMainRowStableIdentity(*row)] = true;
    const int lineIndex =
      nativeUiPlaylistLineIndexForRow(itemLines, *row, &claimed);
    if (lineIndex >= 0 &&
        lineIndex < static_cast<int>(selected.size())) {
      selected[static_cast<size_t>(lineIndex)] = true;
      claimed[static_cast<size_t>(lineIndex)] = true;
    }
  }
  if (std::find(selected.begin(), selected.end(), true) == selected.end()) {
    const auto& sourceRow =
      g_nativeAppActivePanelModel.rows[
        static_cast<size_t>(sourceModelIndex)];
    const int fallback =
      nativeUiPlaylistLineIndexForRow(itemLines, sourceRow);
    if (fallback < 0 || fallback >= static_cast<int>(selected.size())) {
      return false;
    }
    selected[static_cast<size_t>(fallback)] = true;
    selectedIdentities[nativeUiMainRowStableIdentity(
      g_nativeAppActivePanelModel.rows[
        static_cast<size_t>(sourceModelIndex)])] = true;
  }
  // Igual a expand_hash_parent_selection: só os filhos contíguos daquela
  // família acompanham o pai. A seleção visual original não é expandida.
  nativeUiExpandSelectedFamilyParents(
    itemLines, selected, nativeUiPlaylistLineFamilyInfo);

  int targetLineIndex = targetModelIndex;
  if (targetModelIndex >= 0 && targetModelIndex <
      static_cast<int>(g_nativeAppActivePanelModel.rows.size())) {
    targetLineIndex = nativeUiPlaylistLineIndexForRow(
      itemLines,
      g_nativeAppActivePanelModel.rows[
        static_cast<size_t>(targetModelIndex)]);
    if (targetLineIndex < 0) return false;
  } else if (targetModelIndex >=
             static_cast<int>(g_nativeAppActivePanelModel.rows.size())) {
    targetLineIndex = static_cast<int>(itemLines.size());
  }
  targetLineIndex = std::max(0,
    std::min(targetLineIndex, static_cast<int>(itemLines.size())));
  targetLineIndex = nativeUiClampFamilyReorderTarget(
    itemLines, selected, targetLineIndex,
    nativeUiPlaylistLineFamilyInfo);
  auto reordered = nativeUiMoveSelectedItems(
    itemLines, selected, targetLineIndex);
  reordered = nativeUiNormalizeFamilyOrder(
    reordered, nativeUiPlaylistLineFamilyInfo);
  if (reordered == itemLines) return true;
  itemLines = reordered;
  if (!nativeUiSavePlaylistRecords(project, playlists)) return false;

  // Igual ao Lua: primeiro a colecao oficial recebe a nova ordem; depois a
  // interface deriva dela cor de bloco, indices e selecao. Nao movemos o vetor
  // desenhado e nao aguardamos outro snapshot disputar com ele.
  g_nativeMainPendingDropSelectionIdentities = selectedIdentities;
  g_nativeMainPendingDropSelectionRegionsPage = false;
  nativeUiSynchronizePlaylistSourceAfterDrop(project);
  g_nativeUiLastModelRefreshAt =
    std::chrono::steady_clock::time_point{};
  nativeRefreshAppActivePanelModel();
  return true;
}

static bool nativeUiReorderRegionRows(
  int sourceModelIndex,
  int targetModelIndex)
{
  if (sourceModelIndex < 0 || sourceModelIndex >=
      static_cast<int>(g_nativeAppActivePanelModel.rows.size())) {
    return false;
  }
  char pathBuf[2048] = "";
  ReaProject* project = getCurrentProject(
    pathBuf, static_cast<int>(sizeof(pathBuf)));
  if (!project) return false;
  std::vector<NativeSongWindow> songs;
  {
    std::lock_guard<std::mutex> lock(g_nativeMutex);
    songs = g_nativeSongWindows;
  }
  if (songs.empty()) return false;

  const auto& sourceRow = g_nativeAppActivePanelModel.rows[
    static_cast<size_t>(sourceModelIndex)];
  if (sourceRow.child) return false;
  const auto selectedRows = nativeUiSelectedModelRows(true, true);
  std::map<std::string, bool> selectedIdentities;
  std::map<std::string, bool> selectedSongIds;
  for (const auto* row : selectedRows) {
    if (!row) continue;
    selectedIdentities[nativeUiMainRowStableIdentity(*row)] = true;
    selectedSongIds[row->id] = true;
  }
  if (selectedSongIds.empty()) {
    selectedSongIds[sourceRow.id] = true;
    selectedIdentities[nativeUiMainRowStableIdentity(sourceRow)] = true;
  }

  std::vector<bool> selectedSongs(songs.size(), false);
  for (size_t index = 0; index < songs.size(); ++index) {
    selectedSongs[index] = selectedSongIds.find(songs[index].id) !=
      selectedSongIds.end();
  }
  nativeUiExpandSelectedFamilyParents(
    songs, selectedSongs, nativeUiSongFamilyInfo);
  std::map<std::string, bool> movingSongIds;
  for (size_t index = 0; index < songs.size(); ++index) {
    if (selectedSongs[index]) movingSongIds[songs[index].id] = true;
  }
  int targetSongIndex = static_cast<int>(songs.size());
  if (targetModelIndex >= 0 && targetModelIndex <
      static_cast<int>(g_nativeAppActivePanelModel.rows.size())) {
    const auto& targetRow = g_nativeAppActivePanelModel.rows[
      static_cast<size_t>(targetModelIndex)];
    for (size_t index = 0; index < songs.size(); ++index) {
      if (songs[index].id == targetRow.id &&
          std::fabs(songs[index].start - targetRow.start) <= 0.003) {
        targetSongIndex = static_cast<int>(index);
        break;
      }
    }
  }
  targetSongIndex = nativeUiClampFamilyReorderTarget(
    songs, selectedSongs, targetSongIndex,
    nativeUiSongFamilyInfo);
  auto reordered = nativeUiMoveSelectedItems(
    songs, selectedSongs, targetSongIndex);
  reordered = nativeUiNormalizeFamilyOrder(
    reordered, nativeUiSongFamilyInfo);
  bool changed = reordered.size() != songs.size();
  if (!changed) {
    for (size_t index = 0; index < songs.size(); ++index) {
      if (reordered[index].id != songs[index].id ||
          std::fabs(reordered[index].start - songs[index].start) > 0.000001 ||
          std::fabs(reordered[index].end - songs[index].end) > 0.000001) {
        changed = true;
        break;
      }
    }
  }
  if (!changed) return true;
  if (!nativeSaveRegionOrder(project, reordered)) return false;
  {
    std::lock_guard<std::mutex> lock(g_nativeMutex);
    g_nativeSongWindows = reordered;
  }

  // Mantém o modelo visual na mesma ordem até o próximo snapshot. Assim o
  // mouse-up já exibe a música movida azul, sem um quadro intermediário em que
  // a seleção desaparece.
  std::vector<bool> selectedModel(
    g_nativeAppActivePanelModel.rows.size(), false);
  for (size_t index = 0;
       index < g_nativeAppActivePanelModel.rows.size(); ++index) {
    selectedModel[index] = movingSongIds.find(
      g_nativeAppActivePanelModel.rows[index].id) !=
      movingSongIds.end();
  }
  const int clampedTargetModelIndex = nativeUiClampFamilyReorderTarget(
    g_nativeAppActivePanelModel.rows, selectedModel,
    targetModelIndex, nativeUiModelRowFamilyInfo);
  g_nativeAppActivePanelModel.rows = nativeUiNormalizeFamilyOrder(
    nativeUiMoveSelectedItems(
      g_nativeAppActivePanelModel.rows,
      selectedModel, clampedTargetModelIndex),
    nativeUiModelRowFamilyInfo);
  for (size_t index = 0;
       index < g_nativeAppActivePanelModel.rows.size(); ++index) {
    g_nativeAppActivePanelModel.rows[index].order =
      static_cast<int>(index) + 1;
  }
  g_nativeMainVisibleRowIndices = nativeUiBuildVisibleRowIndices();
  nativeUiRestoreSelectionAfterMainReorder(
    selectedIdentities, true);
  g_nativeUiRowsSourceSignatureValid = false;
  ++g_nativeUiRowsGeneration;
  g_nativeForceSnapshotBuild.store(true);
  g_nativeForceStateBuild.store(true);
  return true;
}

static bool nativeUiReorderMainRows(
  int sourceModelIndex,
  int targetVisibleIndex,
  bool regionsPage)
{
  std::map<std::string, bool> selectedIdentities;
  for (const auto* row :
       nativeUiSelectedModelRows(regionsPage, true)) {
    if (row) {
      selectedIdentities[nativeUiMainRowStableIdentity(*row)] = true;
    }
  }
  if (selectedIdentities.empty() && sourceModelIndex >= 0 &&
      sourceModelIndex < static_cast<int>(
        g_nativeAppActivePanelModel.rows.size())) {
    selectedIdentities[nativeUiMainRowStableIdentity(
      g_nativeAppActivePanelModel.rows[
        static_cast<size_t>(sourceModelIndex)])] = true;
  }

  const int targetModelIndex =
    nativeUiMainDragTargetModelIndex(targetVisibleIndex);
  const bool reordered = regionsPage
    ? nativeUiReorderRegionRows(sourceModelIndex, targetModelIndex)
    : nativeUiReorderPlaylistRows(sourceModelIndex, targetModelIndex);
  if (!reordered) return false;

  char pathBuf[2048] = "";
  ReaProject* project = getCurrentProject(
    pathBuf, static_cast<int>(sizeof(pathBuf)));
  const bool transportPlaying =
    project && GetPlayStateEx_ptr &&
    GetPlayStateEx_ptr(project) != 0;
  if (transportPlaying) {
    // Igual ao Lua: durante playback o drop não deixa azul preso. A música
    // que estava na fila continua na fila e volta ao visual laranja/amarelo.
    g_nativeMainPendingDropSelectionIdentities.clear();
    nativeUiClearMainRowSelectionForPage(regionsPage);
  } else {
    // Repertorio ja foi reconstruido sincronicamente pela fonte persistida.
    // Deixar outra selecao pendente aqui fazia o clique seguinte voltar para a
    // musica arrastada. Regioes ainda usa o snapshot assincrono original.
    if (regionsPage) {
      g_nativeMainPendingDropSelectionIdentities = selectedIdentities;
      g_nativeMainPendingDropSelectionRegionsPage = true;
    } else {
      g_nativeMainPendingDropSelectionIdentities.clear();
    }
    nativeUiRestoreSelectionAfterMainReorder(
      selectedIdentities, regionsPage);
  }
  return true;
}

static bool nativeUiFindSongForRow(
  const NativeAppActivePanelModel::Row& row,
  NativeSongWindow& songOut)
{
  std::lock_guard<std::mutex> lock(g_nativeMutex);
  const NativeSongWindow* fallback = nullptr;
  for (const auto& song : g_nativeSongWindows) {
    if (song.isBlock) continue;
    const bool boundsMatch =
      std::fabs(song.start - row.start) <= 0.003 &&
      std::fabs(song.end - row.end) <= 0.003;
    if (song.id == row.id && boundsMatch) {
      songOut = song;
      return true;
    }
    if (!fallback && boundsMatch &&
        song.sourceNumber == row.sourceNumber) {
      fallback = &song;
    }
  }
  if (!fallback) return false;
  songOut = *fallback;
  return true;
}

static std::string nativeUiPlaylistItemLineForSong(
  const NativeSongWindow& song)
{
  int parentNumber = 0;
  int parentEnumIndex = song.parentEnumIndex;
  std::string parentName = song.parentName;
  if (!song.parentId.empty()) {
    std::lock_guard<std::mutex> lock(g_nativeMutex);
    for (const auto& candidate : g_nativeSongWindows) {
      if (candidate.id != song.parentId || candidate.isBlock) continue;
      parentNumber = candidate.sourceNumber;
      if (parentEnumIndex < 0) parentEnumIndex = candidate.enumIndex;
      if (parentName.empty()) parentName = candidate.name;
      break;
    }
  }

  const bool storedMarkerChild = song.isHashChild && !song.isRegionChild;
  std::vector<std::string> fields = {
    "ITEM",
    "region",
    std::to_string(song.sourceNumber),
    nativeNumber(song.start),
    nativeNumber(song.end),
    nativeEscapeExtField(song.name),
    "",
    storedMarkerChild ? "marker" : "region",
    song.isHashParent ? "1" : "0",
    storedMarkerChild ? "1" : "0",
    storedMarkerChild ? std::to_string(song.sourceNumber) : "",
    storedMarkerChild && song.enumIndex >= 0
      ? std::to_string(song.enumIndex) : "",
    parentNumber != 0 ? std::to_string(parentNumber) : "",
    parentEnumIndex >= 0 ? std::to_string(parentEnumIndex) : "",
    nativeEscapeExtField(parentName)
  };
  return nativeUiJoinFields(fields);
}

static bool nativeUiPlaylistContainsSong(
  const NativeUiPlaylistRecord& playlist,
  const NativeSongWindow& song)
{
  for (const std::string& itemLine : playlist.itemLines) {
    const auto fields = nativeSplit(itemLine, '\t');
    if (fields.size() < 5 || fields[0] != "ITEM") continue;
    const int sourceNumber = std::atoi(fields[2].c_str());
    const double start = std::atof(fields[3].c_str());
    const double end = std::atof(fields[4].c_str());
    if (sourceNumber == song.sourceNumber &&
        std::fabs(start - song.start) <= 0.000001 &&
        std::fabs(end - song.end) <= 0.000001) {
      return true;
    }
  }
  return false;
}

static void nativeUiSmartSearchApplyPendingLayout()
{
  const auto now = std::chrono::steady_clock::now();
  if (g_nativeMainSmartSearchScrollTarget.pending &&
      g_nativeMainSmartSearchScrollTarget.expiresAt
          .time_since_epoch().count() != 0 &&
      now >= g_nativeMainSmartSearchScrollTarget.expiresAt) {
    g_nativeMainSmartSearchScrollTarget =
      NativeUiSmartSearchScrollTarget{};
    return;
  }
  if (g_nativeAppActivePanelModel.mixerPage ||
      g_nativeAppActivePanelModel.regionsPage !=
        g_nativeMainSmartSearchExpectedRegionsPage) {
    return;
  }

  const bool regionsPage =
    g_nativeAppActivePanelModel.regionsPage;
  const bool queuedBoundsMatchRequested =
    g_nativeMainSmartSearchScrollTarget.waitForQueue &&
    g_nativeAppActivePanelModel.queueActive &&
    std::fabs(g_nativeAppActivePanelModel.queuedStart -
      g_nativeMainSmartSearchScrollTarget.start) <= 0.003 &&
    std::fabs(g_nativeAppActivePanelModel.queuedEnd -
      g_nativeMainSmartSearchScrollTarget.end) <= 0.003;
  const bool queuedIdMatchesRequested =
    g_nativeMainSmartSearchScrollTarget.waitForQueue &&
    g_nativeAppActivePanelModel.queueActive &&
    !g_nativeMainSmartSearchScrollTarget.id.empty() &&
    g_nativeAppActivePanelModel.queuedId ==
      g_nativeMainSmartSearchScrollTarget.id;
  const bool requestedQueueConfirmed =
    queuedBoundsMatchRequested ||
    queuedIdMatchesRequested;
  if (g_nativeMainSmartSearchSelectFirstPending) {
    for (size_t visible = 0;
         visible < g_nativeMainVisibleRowIndices.size(); ++visible) {
      const size_t source =
        g_nativeMainVisibleRowIndices[visible];
      if (source >= g_nativeAppActivePanelModel.rows.size()) continue;
      const auto& row =
        g_nativeAppActivePanelModel.rows[source];
      if (row.block) continue;
      nativeUiClearMainRowSelectionForPage(regionsPage);
      nativeUiSetMainRowSelected(row, regionsPage, true);
      g_nativeUiSelectionAnchorVisibleIndex =
        static_cast<int>(visible);
      g_nativeUiSelectionFocusVisibleIndex =
        static_cast<int>(visible);
      g_nativeUiMusicSelectionVisualActive = true;
      g_nativeMainNavigationFocus =
        regionsPage ? "regions" : "playlist";
      g_nativeMainSmartSearchSelectFirstPending = false;
      break;
    }
  }

  if (!g_nativeMainSmartSearchScrollTarget.pending ||
      g_nativeMainSmartSearchScrollTarget.regionsPage !=
        regionsPage) {
    return;
  }
  for (size_t visible = 0;
       visible < g_nativeMainVisibleRowIndices.size(); ++visible) {
    const size_t source =
      g_nativeMainVisibleRowIndices[visible];
    if (source >= g_nativeAppActivePanelModel.rows.size() ||
        visible >= g_nativeMainRowOffsets.size() ||
        visible >= g_nativeMainRowHeights.size()) {
      continue;
    }
    const auto& row =
      g_nativeAppActivePanelModel.rows[source];
    const bool exactIdMatch = nativeAppActiveRowMatches(row,
      g_nativeMainSmartSearchScrollTarget.id,
      g_nativeMainSmartSearchScrollTarget.start,
      g_nativeMainSmartSearchScrollTarget.end);
    const bool stableRegionMatch =
      g_nativeMainSmartSearchScrollTarget.end >
        g_nativeMainSmartSearchScrollTarget.start + 0.0005 &&
      (g_nativeMainSmartSearchScrollTarget.sourceNumber == 0 ||
       row.sourceNumber == 0 ||
       std::abs(row.sourceNumber) ==
         std::abs(
           g_nativeMainSmartSearchScrollTarget.sourceNumber)) &&
      std::fabs(row.start -
        g_nativeMainSmartSearchScrollTarget.start) <= 0.003 &&
      std::fabs(row.end -
        g_nativeMainSmartSearchScrollTarget.end) <= 0.003;
    const bool queuedRowMatch =
      requestedQueueConfirmed &&
      nativeAppActiveRowMatches(row,
        g_nativeAppActivePanelModel.queuedId,
        g_nativeAppActivePanelModel.queuedStart,
        g_nativeAppActivePanelModel.queuedEnd);
    if (!queuedRowMatch &&
        !exactIdMatch && !stableRegionMatch) {
      continue;
    }
    const int rowTop =
      g_nativeMainRowOffsets[visible];
    const int rowBottom = rowTop +
      g_nativeMainRowHeights[visible];
    // A lupa posiciona o resultado um pouco acima do meio para deixar contexto
    // abaixo. Nas ultimas musicas, o clamp cai exatamente no mesmo limite que
    // o usuario alcanca rolando a lista manualmente.
    const int searchScrollMaximum =
      g_nativeMainListMaxScrollPixels;
    const int desiredCenterY = static_cast<int>(std::floor(
      g_nativeMainListViewportPixels * 0.42 + 0.5));
    const int rowCenter = rowTop +
      std::max(0, rowBottom - rowTop) / 2;
    g_nativeAppActiveListScrollPixels = std::max(0,
      std::min(searchScrollMaximum,
        rowCenter - desiredCenterY));
    if (!g_nativeMainSmartSearchScrollTarget.waitForQueue) {
      g_nativeMainSmartSearchScrollTarget =
        NativeUiSmartSearchScrollTarget{};
      break;
    }

    // Enfileirar pela lupa reconstrói o repertório e publica uma nova revisão
    // de scroll depois do primeiro paint. O alvo só pode ser liberado quando a
    // própria fila já aponta para essa música e a revisão parou de mudar.
    if (!requestedQueueConfirmed ||
        !queuedRowMatch) break;

    const uint64_t scrollRevision =
      g_nativeAppActivePanelModel.listScrollRevision;
    if (!g_nativeMainSmartSearchScrollTarget.queueWasConfirmed ||
        g_nativeMainSmartSearchScrollTarget
            .lastObservedScrollRevision != scrollRevision) {
      g_nativeMainSmartSearchScrollTarget.queueWasConfirmed = true;
      g_nativeMainSmartSearchScrollTarget
        .lastObservedScrollRevision = scrollRevision;
      g_nativeMainSmartSearchScrollTarget.settleUntil =
        now + std::chrono::milliseconds(700);
      break;
    }
    if (now >=
        g_nativeMainSmartSearchScrollTarget.settleUntil) {
      g_nativeMainSmartSearchScrollTarget =
        NativeUiSmartSearchScrollTarget{};
    }
    break;
  }
}

static void nativeUiOpenCreatePlaylist()
{
  g_nativeUiCreatePlaylistInput.clear();
  g_nativeUiCreatePlaylistInputCursor = 0;
  g_nativeUiCreatePlaylistInputFocused = true;
  g_nativeUiTextSelectionKind =
    NativeUiTextInputKind::CreatePlaylist;
  g_nativeUiTextSelectionAnchor = 0;
  g_nativeMainModalKind = NativeMainModalKind::CreatePlaylist;
}

static std::vector<NativeSongWindow>
nativeUiPlaylistSongsFromRegionSelection()
{
  std::vector<NativeSongWindow> songs;
  {
    std::lock_guard<std::mutex> lock(g_nativeMutex);
    songs = g_nativeSongWindows;
  }
  std::vector<NativeSongWindow> result;
  NativeUiPlaylistRecord dedupe;
  for (const auto* row : nativeUiSelectedModelRows(true)) {
    NativeSongWindow selected;
    if (!row || !nativeUiFindSongForRow(*row, selected)) continue;
    if (selected.isHashChild || selected.isRegionChild) {
      const NativeSongWindow* parent =
        nativeFindFamilyParent(selected, songs);
      if (!parent) continue;
      selected = *parent;
    }
    if (nativeUiPlaylistContainsSong(dedupe, selected)) continue;
    dedupe.itemLines.push_back(
      nativeUiPlaylistItemLineForSong(selected));
    result.push_back(std::move(selected));
  }
  return result;
}

static bool nativeUiSongBelongsToFamily(
  const NativeSongWindow& child,
  const NativeSongWindow& parent)
{
  if (!(child.isHashChild || child.isRegionChild)) return false;
  const bool sameId =
    !parent.id.empty() && !child.parentId.empty() &&
    child.parentId == parent.id;
  const bool sameEnum =
    parent.enumIndex >= 0 && child.parentEnumIndex >= 0 &&
    child.parentEnumIndex == parent.enumIndex;
  return sameId || sameEnum;
}

static void nativeUiRemoveLooseFamilyChildren(
  NativeUiPlaylistRecord& playlist,
  const NativeSongWindow& parent,
  const std::vector<NativeSongWindow>& songs)
{
  playlist.itemLines.erase(
    std::remove_if(
      playlist.itemLines.begin(), playlist.itemLines.end(),
      [&](const std::string& itemLine) {
        const auto fields = nativeSplit(itemLine, '\t');
        if (fields.size() < 5 || fields[0] != "ITEM") return false;
        const int sourceNumber = std::atoi(fields[2].c_str());
        const double start = std::atof(fields[3].c_str());
        const double end = std::atof(fields[4].c_str());
        for (const auto& child : songs) {
          if (!nativeUiSongBelongsToFamily(child, parent)) continue;
          if (sourceNumber == child.sourceNumber &&
              std::fabs(start - child.start) <= 0.000001 &&
              std::fabs(end - child.end) <= 0.000001) {
            return true;
          }
        }
        return false;
      }),
    playlist.itemLines.end());
}

static bool nativeUiCreatePlaylistFromSelection()
{
  const std::string name =
    nativeUpperNamePtBr(nativeTrim(g_nativeUiCreatePlaylistInput));
  if (name.empty()) return false;

  char pathBuf[2048] = "";
  ReaProject* project =
    getCurrentProject(pathBuf, static_cast<int>(sizeof(pathBuf)));
  if (!project) return false;
  std::vector<NativeUiPlaylistRecord> playlists =
    nativeUiReadPlaylistRecords(project);
  for (const auto& playlist : playlists) {
    if (nativeUpperNamePtBr(nativeTrim(playlist.name)) == name) {
      return false;
    }
  }

  NativeUiPlaylistRecord created;
  created.name = name;
  for (const auto& song :
       nativeUiPlaylistSongsFromRegionSelection()) {
    if (nativeUiPlaylistContainsSong(created, song)) continue;
    created.itemLines.push_back(nativeUiPlaylistItemLineForSong(song));
  }
  playlists.push_back(std::move(created));
  if (!nativeUiSavePlaylistRecords(project, playlists)) return false;
  if (SetProjExtState_ptr) {
    SetProjExtState_ptr(project, kPlaylistExtSection,
      "LAST_PLAYLIST_NAME_V1", name.c_str());
  }
  nativeUiClearMainRowSelection();
  nativeApplySelectionCommand(
    "{\"type\":\"set_page\",\"page\":\"playlist\"}");
  nativeUiCloseMainModal();
  return true;
}

static void nativeUiOpenSelectPlaylist(
  NativeUiSelectPlaylistMode mode =
    NativeUiSelectPlaylistMode::AddSelection)
{
  char pathBuf[2048] = "";
  ReaProject* project =
    getCurrentProject(pathBuf, static_cast<int>(sizeof(pathBuf)));
  g_nativeUiPlaylists = project
    ? nativeUiReadPlaylistRecords(project)
    : std::vector<NativeUiPlaylistRecord>{};
  g_nativeUiSelectPlaylistMode = mode;
  g_nativeUiTargetPlaylistIndex = -1;
  if (!g_nativeUiPlaylists.empty()) {
    g_nativeUiTargetPlaylistIndex = 0;
    if (mode == NativeUiSelectPlaylistMode::ExportPlaylist &&
        project) {
      const int current = nativeUiCurrentPlaylistIndex(
        project, g_nativeUiPlaylists);
      if (current >= 0 &&
          current < static_cast<int>(g_nativeUiPlaylists.size())) {
        g_nativeUiTargetPlaylistIndex = current;
      }
    }
  }
  g_nativeUiTargetPlaylistScroll = 0;
  g_nativeUiTargetPlaylistVisibleRows = 1;
  g_nativeUiTargetPlaylistRowHits.clear();
  g_nativeMainModalKind = NativeMainModalKind::SelectPlaylist;
}

static bool nativeUiAddSelectionToPlaylist()
{
  if (g_nativeUiTargetPlaylistIndex < 0 ||
      g_nativeUiTargetPlaylistIndex >=
        static_cast<int>(g_nativeUiPlaylists.size())) {
    return false;
  }
  char pathBuf[2048] = "";
  ReaProject* project =
    getCurrentProject(pathBuf, static_cast<int>(sizeof(pathBuf)));
  if (!project) return false;

  auto& target =
    g_nativeUiPlaylists[static_cast<size_t>(g_nativeUiTargetPlaylistIndex)];
  std::vector<NativeSongWindow> songs;
  {
    std::lock_guard<std::mutex> lock(g_nativeMutex);
    songs = g_nativeSongWindows;
  }
  for (const auto& song :
       nativeUiPlaylistSongsFromRegionSelection()) {
    if (song.isHashParent) {
      nativeUiRemoveLooseFamilyChildren(
        target, song, songs);
    }
    if (!nativeUiPlaylistContainsSong(target, song)) {
      target.itemLines.push_back(nativeUiPlaylistItemLineForSong(song));
    }
  }
  if (!nativeUiSavePlaylistRecords(project, g_nativeUiPlaylists)) {
    return false;
  }
  if (SetProjExtState_ptr) {
    SetProjExtState_ptr(project, kPlaylistExtSection,
      "LAST_PLAYLIST_NAME_V1", target.name.c_str());
  }
  nativeUiClearMainRowSelection();
  nativeApplySelectionCommand(
    "{\"type\":\"set_page\",\"page\":\"playlist\"}");
  nativeUiCloseMainModal();
  return true;
}

static std::vector<const NativeAppActivePanelModel::Row*>
nativeUiSelectedPlaylistRowsForEdit()
{
  auto rows = nativeUiSelectedModelRows(false, true);
  if (!rows.empty() || g_nativeAppActivePanelModel.regionsPage) {
    return rows;
  }

  // Igual ao Lua: quando nao existe multisselecao explicita, a linha azul
  // atual ainda e o alvo da tecla Delete.
  for (const auto& row : g_nativeAppActivePanelModel.rows) {
    if (nativeAppActiveRowMatches(row,
          g_nativeAppActivePanelModel.selectedId,
          g_nativeAppActivePanelModel.selectedStart,
          g_nativeAppActivePanelModel.selectedEnd)) {
      rows.push_back(&row);
      break;
    }
  }
  return rows;
}

static std::string nativeUiDeletePlaylistItemsPrompt()
{
  int musicCount = 0;
  int blockCount = 0;
  for (const auto* row : nativeUiSelectedPlaylistRowsForEdit()) {
    if (!row) continue;
    if (row->block) ++blockCount;
    else ++musicCount;
  }
  if (musicCount > 0 && blockCount > 0) {
    return "Deseja excluir " + std::to_string(musicCount) +
      (musicCount == 1 ? " musica e " : " musicas e ") +
      std::to_string(blockCount) +
      (blockCount == 1 ? " item bloco" : " itens blocos") +
      " do repertorio atual?";
  }
  if (blockCount > 0) {
    return blockCount == 1
      ? "Deseja excluir este bloco do repertorio atual?"
      : "Deseja excluir " + std::to_string(blockCount) +
        " blocos do repertorio atual?";
  }
  if (musicCount > 0) {
    return musicCount == 1
      ? "Deseja excluir esta musica do repertorio atual?"
      : "Deseja excluir " + std::to_string(musicCount) +
        " musicas do repertorio atual?";
  }
  return "Excluir os itens selecionados do repertorio atual?";
}

static bool nativeUiRemoveSelectedPlaylistItems()
{
  char pathBuf[2048] = "";
  ReaProject* project = getCurrentProject(
    pathBuf, static_cast<int>(sizeof(pathBuf)));
  if (!project) return false;
  auto playlists = nativeUiReadPlaylistRecords(project);
  const int playlistIndex =
    nativeUiCurrentPlaylistIndex(project, playlists);
  if (playlistIndex < 0 ||
      playlistIndex >= static_cast<int>(playlists.size())) {
    return false;
  }

  std::vector<int> itemIndices;
  std::map<int, bool> emitted;
  for (const auto* row : nativeUiSelectedPlaylistRowsForEdit()) {
    if (!row) continue;
    const int index = row->order - 1;
    if (index < 0 || emitted[index]) continue;
    emitted[index] = true;
    itemIndices.push_back(index);
  }
  if (itemIndices.empty()) return false;
  auto& lines = playlists[static_cast<size_t>(playlistIndex)].itemLines;
  std::sort(itemIndices.begin(), itemIndices.end(),
    std::greater<int>());
  bool changed = false;
  for (const int index : itemIndices) {
    if (index < 0 || index >= static_cast<int>(lines.size())) continue;
    lines.erase(lines.begin() + index);
    changed = true;
  }
  if (!changed || !nativeUiSavePlaylistRecords(project, playlists)) {
    return false;
  }
  nativeUiClearMainRowSelection();
  g_nativeAppActiveListScrollPixels = 0;
  return true;
}

static std::string nativeUiFormatBlockNameForCurrentSymbol(
  const std::string& rawSuffix)
{
  std::string suffix = nativeUpperNamePtBrKeepParentheses(
    nativeTrim(rawSuffix));
  if (suffix.empty()) suffix = "01";
  // O ornamento agora pertence somente ao desenho. Nomes novos permanecem
  // limpos no projeto/repertorio e nao carregam sequencias de caracteres.
  return "BLOCO " + suffix;
}

static std::string nativeUiFormatDefaultBlockName(int blockNumber)
{
  std::ostringstream suffix;
  suffix << std::setw(2) << std::setfill('0')
         << std::max(1, blockNumber);
  return nativeUiFormatBlockNameForCurrentSymbol(suffix.str());
}

static bool nativeUiCreatePlaylistBlock()
{
  char pathBuf[2048] = "";
  ReaProject* project =
    getCurrentProject(pathBuf, static_cast<int>(sizeof(pathBuf)));
  if (!project) return false;
  std::vector<NativeUiPlaylistRecord> playlists =
    nativeUiReadPlaylistRecords(project);
  const int playlistIndex =
    nativeUiCurrentPlaylistIndex(project, playlists);
  if (playlistIndex < 0 ||
      playlistIndex >= static_cast<int>(playlists.size())) {
    return false;
  }

  auto& playlist = playlists[static_cast<size_t>(playlistIndex)];
  const auto blockNumberFromLine =
    [](const std::string& itemLine) -> int {
    const auto fields = nativeSplit(itemLine, '\t');
    if (fields.size() < 3 || fields[0] != "ITEM") return 0;
    const int sourceNumber = std::atoi(fields[2].c_str());
    const bool isBlock =
      (fields.size() > 1 && fields[1] == "block") ||
      sourceNumber < 0;
    if (!isBlock) return 0;
    if (sourceNumber != 0) return std::abs(sourceNumber);

    // Compatibilidade com repertorios antigos cujo cabecalho de bloco nao
    // possuia numero negativo no campo sourceNumber.
    const std::string name = fields.size() > 5
      ? nativeUpperAscii(nativeUnescapeExtField(fields[5]))
      : std::string();
    const size_t marker = name.find("BLOCO");
    if (marker == std::string::npos) return 0;
    return std::max(0, std::atoi(name.c_str() + marker + 5));
  };

  int previousBlockNumber = 0;
  for (const std::string& itemLine : playlist.itemLines) {
    previousBlockNumber = std::max(
      previousBlockNumber,
      blockNumberFromLine(itemLine));
  }
  const int blockNumber = previousBlockNumber + 1;

  size_t insertIndex = 0;
  if (previousBlockNumber > 0) {
    size_t previousBlockIndex = playlist.itemLines.size();
    for (size_t index = 0;
         index < playlist.itemLines.size(); ++index) {
      if (blockNumberFromLine(playlist.itemLines[index]) ==
          previousBlockNumber) {
        previousBlockIndex = index;
        break;
      }
    }

    if (previousBlockIndex < playlist.itemLines.size()) {
      // O novo bloco nasce imediatamente abaixo do cabecalho de maior numero,
      // independentemente de onde ele esteja no repertorio.
      insertIndex = previousBlockIndex + 1;
    }
  }

  const std::vector<std::string> fields = {
    "ITEM", "block", std::to_string(-blockNumber),
    "0", "0",
    nativeEscapeExtField(nativeUiFormatDefaultBlockName(blockNumber)),
    "", "", "0", "0", "", "", "", "", ""
  };
  const std::string blockLine = nativeUiJoinFields(fields);
  playlist.itemLines.insert(
    playlist.itemLines.begin() + static_cast<std::ptrdiff_t>(insertIndex),
    blockLine);
  return nativeUiSavePlaylistRecords(project, playlists);
}

