struct NativeUiTrackRoutingSnapshot {
  MediaTrack* track = nullptr;
  double mainSend = 0.0;
  double mainSendOffset = 0.0;
  double mainSendChannels = 0.0;
};

static std::vector<NativeUiTrackRoutingSnapshot>
nativeUiForceParentSendsForRender(
  ReaProject* project)
{
  std::vector<NativeUiTrackRoutingSnapshot> result;
  if (!project || !CountTracks_ptr ||
      !GetTrack_ptr ||
      !GetMediaTrackInfo_Value_ptr ||
      !SetMediaTrackInfo_Value_ptr) {
    return result;
  }
  const int count = CountTracks_ptr(project);
  result.reserve(static_cast<size_t>(
    std::max(0, count)));
  for (int index = 0; index < count; ++index) {
    MediaTrack* track = GetTrack_ptr(
      project, index);
    if (!track) continue;
    NativeUiTrackRoutingSnapshot snapshot;
    snapshot.track = track;
    snapshot.mainSend =
      GetMediaTrackInfo_Value_ptr(
        track, "B_MAINSEND");
    snapshot.mainSendOffset =
      GetMediaTrackInfo_Value_ptr(
        track, "C_MAINSEND_OFFS");
    snapshot.mainSendChannels =
      GetMediaTrackInfo_Value_ptr(
        track, "C_MAINSEND_NCH");
    result.push_back(snapshot);
    SetMediaTrackInfo_Value_ptr(
      track, "B_MAINSEND", 1.0);
    SetMediaTrackInfo_Value_ptr(
      track, "C_MAINSEND_OFFS", 0.0);
    SetMediaTrackInfo_Value_ptr(
      track, "C_MAINSEND_NCH", 0.0);
  }
  if (TrackList_AdjustWindows_ptr) {
    TrackList_AdjustWindows_ptr(false);
  }
  if (UpdateArrange_ptr) UpdateArrange_ptr();
  return result;
}

static void nativeUiRestoreParentSendsAfterRender(
  const std::vector<NativeUiTrackRoutingSnapshot>&
    snapshot)
{
  if (!SetMediaTrackInfo_Value_ptr) return;
  for (const auto& entry : snapshot) {
    if (!entry.track) continue;
    SetMediaTrackInfo_Value_ptr(
      entry.track, "B_MAINSEND",
      entry.mainSend);
    SetMediaTrackInfo_Value_ptr(
      entry.track, "C_MAINSEND_OFFS",
      entry.mainSendOffset);
    SetMediaTrackInfo_Value_ptr(
      entry.track, "C_MAINSEND_NCH",
      entry.mainSendChannels);
  }
  if (TrackList_AdjustWindows_ptr) {
    TrackList_AdjustWindows_ptr(false);
  }
  if (UpdateArrange_ptr) UpdateArrange_ptr();
}

static bool nativeUiPrepareRegionRenderMatrix(
  ReaProject* project,
  const std::vector<int>& regionNumbers)
{
  if (!project || regionNumbers.empty() ||
      !GetMasterTrack_ptr ||
      !SetRegionRenderMatrix_ptr) {
    return false;
  }
  MediaTrack* master =
    GetMasterTrack_ptr(project);
  if (!master) return false;

  if (CountProjectMarkers_ptr &&
      EnumProjectMarkers3_ptr &&
      EnumRegionRenderMatrix_ptr) {
    int markerCount = 0;
    int regionCount = 0;
    const int total = CountProjectMarkers_ptr(
      project, &markerCount, &regionCount);
    for (int index = 0;
         index < total; ++index) {
      bool isRegion = false;
      double start = 0.0;
      double end = 0.0;
      const char* name = nullptr;
      int number = 0;
      int color = 0;
      if (!EnumProjectMarkers3_ptr(
            project, index, &isRegion, &start,
            &end, &name, &number, &color) ||
          !isRegion) {
        continue;
      }
      for (int slot = 0;; ++slot) {
        MediaTrack* track =
          EnumRegionRenderMatrix_ptr(
            project, number, slot);
        if (!track) break;
        if (track == master) {
          SetRegionRenderMatrix_ptr(
            project, number, master, -1);
          break;
        }
      }
    }
  }

  for (const int number : regionNumbers) {
    SetRegionRenderMatrix_ptr(
      project, number, master, 1);
  }
  return true;
}

static bool nativeUiExecuteExportAudio(
  const std::string& requestedFormat)
{
  char pathBuf[2048] = "";
  ReaProject* project = getCurrentProject(
    pathBuf, static_cast<int>(sizeof(pathBuf)));
  if (!project ||
      g_nativeUiExportRegionNumbers.empty()) {
    g_nativeUiExportInfo =
      "Nenhuma musica selecionada para exportar";
    return false;
  }

  char initialFolder[4096] = "";
  if (GetProjectPathEx_ptr) {
    GetProjectPathEx_ptr(
      project, initialFolder,
      static_cast<int>(sizeof(initialFolder)));
  } else if (pathBuf[0]) {
    std::strncpy(
      initialFolder, pathBuf,
      sizeof(initialFolder) - 1);
  }
  char selectedFolder[4096] = "";
  if (!vshook_jsapi::browseForFolder(
        "Escolha a pasta de exportacao",
        initialFolder, selectedFolder,
        static_cast<int>(sizeof(selectedFolder)))) {
    return false;
  }
  const std::string folder =
    nativeTrim(selectedFolder);
  if (folder.empty()) return false;

  std::string format =
    nativeLower(nativeTrim(requestedFormat));
  if (format != "mp3" && format != "aiff") {
    format = "wav";
  }
  const std::string renderFormat =
    format == "mp3"
      ? "bDNwbQAAAAA="
      : (format == "aiff"
          ? "ZmZpYRgAAA=="
          : "ZXZhdxgAAA==");
  if (!nativeUiPrepareRegionRenderMatrix(
        project,
        g_nativeUiExportRegionNumbers)) {
    g_nativeUiExportInfo =
      "Matrix nao conseguiu marcar as musicas selecionadas";
    return false;
  }

  nativeUiSetProjectString(
    project, "RENDER_FORMAT", renderFormat);
  nativeUiSetProjectString(
    project, "RENDER_FORMAT2", "");
  nativeUiSetProjectString(
    project, "RENDER_FILE", folder);
  nativeUiSetProjectString(
    project, "RENDER_PATTERN", "$region");
  if (GetSetProjectInfo_ptr) {
    GetSetProjectInfo_ptr(
      project, "RENDER_SETTINGS", 8.0, true);
    GetSetProjectInfo_ptr(
      project, "RENDER_BOUNDSFLAG", 5.0, true);
    GetSetProjectInfo_ptr(
      project, "RENDER_CHANNELS", 2.0, true);
    GetSetProjectInfo_ptr(
      project, "RENDER_SRATE", 44100.0, true);
  }

  const auto routing =
    nativeUiForceParentSendsForRender(project);
  const bool canRender =
    Main_OnCommand_ptr != nullptr;
  if (canRender) {
    Main_OnCommand_ptr(42230, 0);
  }
  nativeUiRestoreParentSendsAfterRender(routing);
  if (!canRender) {
    g_nativeUiExportInfo =
      "Nao foi possivel iniciar o render";
    return false;
  }

  g_nativeUiExportFormat = format;
  nativeUiCloseMainModal();
  return true;
}

static long long nativeUiEpochMilliseconds()
{
  return std::chrono::duration_cast<
    std::chrono::milliseconds>(
      std::chrono::system_clock::now()
        .time_since_epoch()).count();
}

static void nativeUiInvalidateDirectorSessions(
  const std::string& reason)
{
  if (!SetExtState_ptr) return;
  const long long nowMs =
    nativeUiEpochMilliseconds();
  const std::string revision =
    std::to_string(nowMs);
  const std::string token =
    reason + "_" + revision;
  SetExtState_ptr("VS_HOOK_NATIVE_BRIDGE",
    "DIRECTOR_AUTH_REVISION_V1",
    revision.c_str(), false);
  SetExtState_ptr("VS_HOOK_NATIVE_BRIDGE",
    "DIRECTOR_LOGOUT_REQUEST_V1",
    token.c_str(), false);
  SetExtState_ptr("VS_HOOK_NATIVE_BRIDGE",
    "DIRECTOR_LOGOUT_REQUEST_AT_V1",
    revision.c_str(), false);
  SetExtState_ptr("VS_HOOK_NATIVE_BRIDGE",
    "DIRECTOR_LOGOUT_COMMAND_V1",
    "director_force_logout", false);
  SetExtState_ptr("VS_HOOK_NATIVE_BRIDGE",
    "DIRECTOR_LOGOUT_TARGET_V1",
    "director", false);
  g_nativeForceSnapshotBuild.store(true);
  g_nativeForceStateBuild.store(true);
}

static std::string nativeUiReadDirectorPassword()
{
  if (!GetExtState_ptr) return std::string();
  const char* direct = GetExtState_ptr(
    kAccessExtSection,
    kAccessDirectorPassKey);
  const std::string normalized =
    nativeTrim(direct ? direct : "");
  if (!normalized.empty()) return normalized;
  const char* legacy = GetExtState_ptr(
    kAccessExtSection,
    kAccessLegacyPassKey);
  return nativeTrim(legacy ? legacy : "");
}

static bool nativeUiBlockInterfaceWhenDirectorConnectedEnabled()
{
  if (!GetExtState_ptr) return true;
  const char* raw = GetExtState_ptr(
    kAccessExtSection,
    kAccessBlockInterfaceWhenDirectorConnectedKey);
  // Ate o usuario escolher, o comportamento padrao e bloquear.
  return nativeBoolFromText(raw ? raw : "", true);
}

static bool nativeUiConfigureDirectorPassword()
{
  if (!GetUserInputs_ptr || !SetExtState_ptr) {
    g_nativeUiConfigAccessInfo =
      "Entrada de senha indisponivel.";
    return false;
  }
  std::vector<char> buffer(4096, '\0');
  const std::string current =
    nativeUiReadDirectorPassword();
  std::memcpy(buffer.data(), current.data(),
    std::min(current.size(), buffer.size() - 1));
  if (!GetUserInputs_ptr(
        "Senha Diretor", 1, "Senha",
        buffer.data(),
        static_cast<int>(buffer.size()))) {
    return false;
  }
  const std::string password =
    nativeTrim(buffer.data());
  SetExtState_ptr(kAccessExtSection,
    kAccessDirectorPassKey,
    password.c_str(), true);
  SetExtState_ptr(kAccessExtSection,
    kAccessUserKey, "", true);
  SetExtState_ptr(kAccessExtSection,
    kAccessLegacyPassKey,
    password.c_str(), true);
  nativeUiInvalidateDirectorSessions(
    "password_change");
  nativeUiCloseMainModal();
  return true;
}

static bool nativeUiConfigureRecadosPassword()
{
  if (!GetUserInputs_ptr || !SetExtState_ptr) {
    g_nativeUiConfigAccessInfo =
      "Entrada de senha indisponivel.";
    return false;
  }
  std::vector<char> buffer(4096, '\0');
  const std::string current =
    nativeReadRecadosPassword();
  std::memcpy(buffer.data(), current.data(),
    std::min(current.size(), buffer.size() - 1));
  if (!GetUserInputs_ptr(
        "Senha App Recados", 1, "Senha",
        buffer.data(),
        static_cast<int>(buffer.size()))) {
    return false;
  }
  const std::string password =
    nativeTrim(buffer.data());
  SetExtState_ptr(kAccessExtSection,
    kAccessRecadosPassKey,
    password.c_str(), true);
  g_nativeForceSnapshotBuild.store(true);
  g_nativeForceStateBuild.store(true);
  nativeUiCloseMainModal();
  return true;
}

static std::string nativeUiBackupEscape(
  const std::string& value)
{
  std::string result;
  result.reserve(value.size());
  for (const char ch : value) {
    if (ch == '\\') result += "\\\\";
    else if (ch == '\r') result += "\\r";
    else if (ch == '\n') result += "\\n";
    else if (ch == '\t') result += "\\t";
    else result.push_back(ch);
  }
  return result;
}

static std::string nativeUiBackupUnescape(
  const std::string& value)
{
  std::string result;
  result.reserve(value.size());
  for (size_t index = 0;
       index < value.size(); ++index) {
    const char ch = value[index];
    if (ch != '\\' || index + 1 >= value.size()) {
      result.push_back(ch);
      continue;
    }
    const char next = value[++index];
    if (next == 'n') result.push_back('\n');
    else if (next == 'r') result.push_back('\r');
    else if (next == 't') result.push_back('\t');
    else result.push_back(next);
  }
  return result;
}

static void nativeUiBackupAddRecord(
  std::vector<std::string>& records,
  const std::string& section,
  const std::string& key,
  const std::string& value)
{
  records.push_back(
    "DATA\tGLOBAL\t" +
    nativeUiBackupEscape(section) + "\t" +
    nativeUiBackupEscape(key) + "\t" +
    nativeUiBackupEscape(value));
}

