        const int indexW = 34;
        const int muteW = 30;
        const int dbW = 58;
        const int gap2 = 5;
        const int topY = rowRect.top + 4;
        const int buttonHeight = 20;
        const int sliderHeight = 10;
        const int sliderY = rowRect.bottom - 14;
        const int nameX = rowRect.left + indexW;
        const int muteX = rowRect.right - 6 - muteW;
