static double nativeTelepromptJsonNumber(
  const std::string& json,
  const char* key,
  double fallback)
{
  const std::string raw = nativeJsonExtractString(json, key ? key : "");
  if (!nativeLooksNumeric(raw)) return fallback;
  return std::atof(raw.c_str());
}

static bool nativeTelepromptJsonBool(
  const std::string& json,
  const char* key,
  bool fallback)
{
  return nativeBoolFromText(
    nativeJsonExtractString(json, key ? key : ""), fallback);
}

static double nativeTelepromptClamp(
  double value,
  double low,
  double high)
{
  return std::max(low, std::min(high, value));
}

static void nativeTelepromptApplySettingsJson(
  NativeTelepromptSettings& next,
  const std::string& json)
{
  auto stringValue = [&](const char* key, std::string& field) {
    const std::string value = nativeTrim(
      nativeJsonExtractString(json, key));
    if (!value.empty()) field = value;
  };
  stringValue("preset", next.preset);
  if (next.preset != "day") next.preset = "night";
  stringValue("textColor", next.textColor);
  stringValue("textBoxColor", next.textBoxColor);
  stringValue("clockColor", next.clockColor);
  stringValue("clockExpiredColor", next.clockExpiredColor);
  stringValue("clockBorderColor", next.clockBorderColor);
  stringValue("localClockColor", next.localClockColor);
  stringValue("borderColor", next.borderColor);
  stringValue("songNameColor", next.songNameColor);
  stringValue("queueNameColor", next.queueNameColor);
  stringValue("progressColor", next.progressColor);
  stringValue("fontFamily", next.fontFamily);
  stringValue("songNameFontFamily", next.songNameFontFamily);
  stringValue("queueNameFontFamily", next.queueNameFontFamily);
  stringValue("textCase", next.textCase);
  stringValue("clockPosition", next.clockPosition);
  stringValue("localClockPosition", next.localClockPosition);
  stringValue("songNamePosition", next.songNamePosition);
  stringValue("queueNamePosition", next.queueNamePosition);
  stringValue("progressPosition", next.progressPosition);
  next.textScale = nativeTelepromptClamp(
    nativeTelepromptJsonNumber(json, "textScale", next.textScale),
    0.35, 1.0);
  next.clockScale = nativeTelepromptClamp(
    nativeTelepromptJsonNumber(json, "clockScale", next.clockScale),
    0.35, 1.0);
  next.songNameScale = nativeTelepromptClamp(
    nativeTelepromptJsonNumber(
      json, "songNameScale", next.songNameScale),
    0.35, 2.0);
  next.queueNameScale = nativeTelepromptClamp(
    nativeTelepromptJsonNumber(
      json, "queueNameScale", next.queueNameScale),
    0.35, 2.0);
  next.mediaScale = nativeTelepromptClamp(
    nativeTelepromptJsonNumber(json, "mediaScale", next.mediaScale),
    0.25, 1.5);
  next.previewScale = nativeTelepromptClamp(
    nativeTelepromptJsonNumber(
      json, "previewScale", next.previewScale),
    0.35, 3.0);
  next.localClockDepth = nativeTelepromptJsonNumber(
    json, "localClockDepth", next.localClockDepth);
  // O primeiro protótipo tratava "profundidade" como deslocamento em pixels.
  // Valores antigos (por exemplo 12) migram para escala neutra.
  if (next.localClockDepth > 3.0) next.localClockDepth = 1.0;
  next.localClockDepth = nativeTelepromptClamp(
    next.localClockDepth, 0.5, 2.0);
  next.windowBorderEnabled = nativeTelepromptJsonBool(
    json, "windowBorderEnabled",
    nativeTelepromptJsonBool(
      json, "borderEnabled", next.windowBorderEnabled));
  next.clockBorderEnabled = nativeTelepromptJsonBool(
    json, "clockBorderEnabled", next.clockBorderEnabled);
  next.textBoxEnabled = nativeTelepromptJsonBool(
    json, "textBoxEnabled", next.textBoxEnabled);
  next.clockEnabled = nativeTelepromptJsonBool(
    json, "clockEnabled", next.clockEnabled);
  next.localClockEnabled = nativeTelepromptJsonBool(
    json, "localClockEnabled", next.localClockEnabled);
  next.songNameEnabled = nativeTelepromptJsonBool(
    json, "songNameEnabled", next.songNameEnabled);
  next.queueNameEnabled = nativeTelepromptJsonBool(
    json, "queueNameEnabled", next.queueNameEnabled);
  next.progressEnabled = nativeTelepromptJsonBool(
    json, "progressEnabled", next.progressEnabled);
  next.previewEnabled = nativeTelepromptJsonBool(
    json, "previewEnabled", next.previewEnabled);
  next.clearMode = nativeTelepromptJsonBool(
    json, "clearMode", next.clearMode);
  const bool legacyRgb = nativeTelepromptJsonBool(
    json, "rgbBorderEnabled", false);
  next.rgbWindowBorderEnabled = nativeTelepromptJsonBool(
    json, "rgbWindowBorderEnabled",
    next.rgbWindowBorderEnabled || legacyRgb);
  next.rgbClockBorderEnabled = nativeTelepromptJsonBool(
    json, "rgbClockBorderEnabled", next.rgbClockBorderEnabled);
  next.rgbTextBoxBorderEnabled = nativeTelepromptJsonBool(
    json, "rgbTextBoxBorderEnabled", next.rgbTextBoxBorderEnabled);
}

