  json << "\"tp2UpdatedAt\":" << nativeJsonString(tp2UpdatedAt) << ",";
  json << "\"nativeTp1MediaStatus\":"
       << g_nativeTelepromptMediaStatus[0].load() << ",";
  json << "\"nativeTp2MediaStatus\":"
       << g_nativeTelepromptMediaStatus[1].load() << ",";
  json << "\"nativeTp1MediaDiagDedicated\":"
       << g_nativeTelepromptMediaDiagDedicated[0].load() << ",";
  json << "\"nativeTp2MediaDiagDedicated\":"
       << g_nativeTelepromptMediaDiagDedicated[1].load() << ",";
  json << "\"nativeTp1MediaDiagTake\":"
       << g_nativeTelepromptMediaDiagTake[0].load() << ",";
  json << "\"nativeTp2MediaDiagTake\":"
       << g_nativeTelepromptMediaDiagTake[1].load() << ",";
  json << "\"nativeTp1MediaDiagParent\":"
       << g_nativeTelepromptMediaDiagParent[0].load() << ",";
  json << "\"nativeTp2MediaDiagParent\":"
       << g_nativeTelepromptMediaDiagParent[1].load() << ",";
